import { useSyncExternalStore, useEffect, useRef } from "react";
import { useParams, Link } from "react-router-dom";
import {
  ArrowLeft,
  Globe,
  Clock,
  AlertTriangle,
  RotateCcw,
  Bot,
  Sparkles,
  ChevronRight,
  ExternalLink,
} from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { Separator } from "@/components/ui/separator";
import { ScrollArea } from "@/components/ui/scroll-area";
import { PageTransition } from "@/components/shared/PageTransition";
import { AgentAvatar } from "@/components/agents/AgentAvatar";
import { AgentStatusBadge } from "@/components/agents/AgentStatusBadge";
import { AgentMessageBubble } from "@/components/agents/AgentMessage";
import { cn } from "@/lib/utils";
import { formatRelativeDate } from "@/lib/score-utils";
import { agentEngine } from "@/lib/agent-engine";
import { MOCK_AGENTS, MOCK_AGENT_TASKS, MOCK_AGENT_MESSAGES } from "@/lib/mock-agents";
import type { AgentStatus } from "@/types/agents";

// ── Component ───────────────────────────────────────────────

const AgentWorkspace = () => {
  const { taskId } = useParams<{ taskId: string }>();
  const task = MOCK_AGENT_TASKS.find((t) => t.id === taskId);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  // Subscribe to engine state via useSyncExternalStore (React 18)
  const engineSnapshot = useSyncExternalStore(
    agentEngine.subscribe.bind(agentEngine),
    () => ({
      messages: agentEngine.getMessages(taskId ?? ""),
      progress: agentEngine.getTaskProgress(taskId ?? ""),
    }),
    () => ({ messages: [], progress: 0 })
  );

  // Start watching the task
  useEffect(() => {
    if (!taskId) return;

    if (task?.status === "completed") {
      agentEngine.loadCompletedTask(taskId);
    } else {
      agentEngine.watchTask(taskId);
    }

    return () => {
      agentEngine.cleanup();
    };
  }, [taskId, task?.status]);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [engineSnapshot.messages.length]);

  if (!task) {
    return (
      <PageTransition>
        <div className="flex flex-col items-center justify-center py-20">
          <p className="text-muted-foreground">Task not found.</p>
          <Button asChild variant="ghost" className="mt-4">
            <Link to="/agents">
              <ArrowLeft className="mr-2 h-4 w-4" />
              Back to Agent Hub
            </Link>
          </Button>
        </div>
      </PageTransition>
    );
  }

  const { messages, progress } = engineSnapshot;
  const assignedAgents = MOCK_AGENTS.filter((a) =>
    task.assigned_agents.includes(a.id)
  );

  let hostname = "";
  try {
    hostname = new URL(task.url).hostname.replace("www.", "");
  } catch {
    hostname = task.url;
  }

  // Count findings from visible messages
  const visibleFindings = messages.filter((m) => m.type === "finding").length;
  const visibleCritical = messages.filter(
    (m) => m.type === "finding" && m.metadata?.severity === "critical"
  ).length;
  const visibleSuggestions = messages.filter(
    (m) => m.type === "suggestion"
  ).length;

  return (
    <PageTransition>
      <div className="space-y-6">
        {/* ── Top Navigation ───────────────────────────────── */}
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Link
            to="/agents"
            className="hover:text-foreground transition-colors flex items-center gap-1"
          >
            <ArrowLeft className="h-3.5 w-3.5" />
            Agent Hub
          </Link>
          <ChevronRight className="h-3 w-3" />
          <span className="text-foreground font-medium truncate">
            {task.title}
          </span>
        </div>

        {/* ── Task Header ──────────────────────────────────── */}
        <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
          <div>
            <h2 className="text-2xl font-bold text-foreground mb-1">
              {task.title}
            </h2>
            <div className="flex items-center gap-3 flex-wrap">
              <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
                <Globe className="h-3.5 w-3.5" />
                <span>{hostname}</span>
              </div>
              <div className="flex items-center gap-1.5 text-sm text-muted-foreground">
                <Clock className="h-3.5 w-3.5" />
                <span>Started {formatRelativeDate(task.created_at)}</span>
              </div>
            </div>
          </div>

          {/* Playback controls (for demo) */}
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => {
                agentEngine.cleanup();
                agentEngine.watchTask(taskId!);
              }}
            >
              <RotateCcw className="h-3.5 w-3.5 mr-1" />
              Replay
            </Button>
          </div>
        </div>

        {/* ── Progress Bar ─────────────────────────────────── */}
        <div className="rounded-xl border border-border/50 bg-card p-4">
          <div className="flex items-center justify-between mb-2">
            <div className="flex items-center gap-2">
              <div
                className={cn(
                  "h-2 w-2 rounded-full",
                  progress < 100
                    ? "bg-blue-500 animate-pulse"
                    : "bg-emerald-500"
                )}
              />
              <span className="text-sm font-medium text-foreground">
                {progress < 100 ? "Agents Working..." : "Analysis Complete"}
              </span>
            </div>
            <span className="text-sm font-semibold text-foreground tabular-nums">
              {progress}%
            </span>
          </div>
          <Progress
            value={progress}
            className="h-2"
          />
          <div className="flex items-center gap-4 mt-3 text-xs text-muted-foreground">
            <span>
              {visibleFindings} finding{visibleFindings !== 1 ? "s" : ""}
              {visibleCritical > 0 && (
                <span className="text-red-500 font-medium ml-1">
                  ({visibleCritical} critical)
                </span>
              )}
            </span>
            <span>{visibleSuggestions} suggestion{visibleSuggestions !== 1 ? "s" : ""}</span>
            <span>{messages.length} messages</span>
          </div>
        </div>

        {/* ── Main Layout: Messages + Agent Sidebar ────────── */}
        <div className="grid grid-cols-1 gap-6 lg:grid-cols-4">
          {/* Left: Live Message Feed (3 cols) */}
          <div className="lg:col-span-3">
            <Card className="border-border/50 shadow-soft">
              <CardHeader className="pb-3">
                <CardTitle className="text-base font-semibold flex items-center gap-2">
                  <Sparkles className="h-4 w-4 text-violet-500" />
                  Live Agent Feed
                  {progress < 100 && (
                    <span className="ml-auto flex items-center gap-1.5 text-xs font-normal text-muted-foreground">
                      <span className="h-1.5 w-1.5 rounded-full bg-blue-500 animate-pulse" />
                      Streaming...
                    </span>
                  )}
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="space-y-3">
                  {messages.length === 0 && progress === 0 && (
                    <div className="flex flex-col items-center py-12 text-center">
                      <div className="flex h-12 w-12 items-center justify-center rounded-xl bg-gradient-to-br from-violet-500 to-purple-600 mb-3">
                        <Bot className="h-6 w-6 text-white" />
                      </div>
                      <p className="text-sm font-medium text-foreground mb-1">
                        Initializing agents...
                      </p>
                      <p className="text-xs text-muted-foreground">
                        Agents are spinning up and preparing to analyze the page.
                      </p>
                    </div>
                  )}

                  {messages.map((msg, idx) => (
                    <AgentMessageBubble
                      key={msg.id}
                      message={msg}
                      isLatest={idx === messages.length - 1 && progress < 100}
                    />
                  ))}

                  {/* Typing indicator */}
                  {progress > 0 && progress < 100 && (
                    <div className="flex items-center gap-2 pl-4 py-2">
                      <div className="flex gap-1">
                        <span className="h-1.5 w-1.5 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: "0ms" }} />
                        <span className="h-1.5 w-1.5 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: "150ms" }} />
                        <span className="h-1.5 w-1.5 rounded-full bg-slate-400 animate-bounce" style={{ animationDelay: "300ms" }} />
                      </div>
                      <span className="text-xs text-muted-foreground">
                        Agents are thinking...
                      </span>
                    </div>
                  )}

                  {/* Completion summary */}
                  {progress === 100 && messages.length > 0 && (
                    <div className="rounded-xl border border-emerald-200 bg-emerald-50/50 p-4 mt-4">
                      <div className="flex items-center gap-2 mb-2">
                        <div className="h-6 w-6 rounded-full bg-emerald-500 flex items-center justify-center">
                          <svg className="h-3.5 w-3.5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3}>
                            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
                          </svg>
                        </div>
                        <span className="text-sm font-semibold text-emerald-800">
                          Analysis Complete
                        </span>
                      </div>
                      <p className="text-xs text-emerald-700 leading-relaxed">
                        All agents have completed their analysis. Found {visibleFindings} findings
                        ({visibleCritical} critical) and generated {visibleSuggestions} AI-powered suggestions.
                        {task.scan_id && (
                          <>
                            {" "}
                            <Link
                              to={`/reports/${task.scan_id}`}
                              className="font-medium underline underline-offset-2 hover:text-emerald-900"
                            >
                              View full audit report →
                            </Link>
                          </>
                        )}
                      </p>
                    </div>
                  )}

                  <div ref={messagesEndRef} />
                </div>
              </CardContent>
            </Card>
          </div>

          {/* Right: Agent Status Panel */}
          <div className="space-y-4">
            {/* Assigned Agents */}
            <Card className="border-border/50 shadow-soft">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold flex items-center gap-2">
                  <Bot className="h-3.5 w-3.5 text-violet-500" />
                  Active Agents
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                {assignedAgents.map((agent) => {
                  const status = agentEngine.getAgentStatus(agent.id);
                  return (
                    <div
                      key={agent.id}
                      className="flex items-center gap-2.5"
                    >
                      <AgentAvatar
                        emoji={agent.emoji}
                        gradient={agent.gradient}
                        status={status}
                        size="sm"
                      />
                      <div className="flex-1 min-w-0">
                        <p className="text-xs font-medium text-foreground truncate">
                          {agent.name}
                        </p>
                        <AgentStatusBadge status={status} className="mt-0.5" />
                      </div>
                    </div>
                  );
                })}
              </CardContent>
            </Card>

            {/* Task Stats */}
            <Card className="border-border/50 shadow-soft">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-semibold">
                  Task Summary
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-3">
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Findings</span>
                  <span className="text-sm font-semibold text-foreground tabular-nums">
                    {visibleFindings}
                  </span>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Critical</span>
                  <span className="text-sm font-semibold text-red-600 tabular-nums">
                    {visibleCritical}
                  </span>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Suggestions</span>
                  <span className="text-sm font-semibold text-violet-600 tabular-nums">
                    {visibleSuggestions}
                  </span>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Page Type</span>
                  <Badge variant="outline" className="text-2xs capitalize">
                    {task.page_type}
                  </Badge>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <span className="text-xs text-muted-foreground">Priority</span>
                  <Badge
                    variant="outline"
                    className={cn(
                      "text-2xs capitalize",
                      task.priority === "critical" && "border-red-200 bg-red-50 text-red-700",
                      task.priority === "high" && "border-orange-200 bg-orange-50 text-orange-700"
                    )}
                  >
                    {task.priority}
                  </Badge>
                </div>
              </CardContent>
            </Card>

            {/* Link to full report */}
            {task.scan_id && (
              <Button asChild variant="outline" className="w-full" size="sm">
                <Link to={`/reports/${task.scan_id}`}>
                  <ExternalLink className="mr-2 h-3.5 w-3.5" />
                  View Full Report
                </Link>
              </Button>
            )}
          </div>
        </div>
      </div>
    </PageTransition>
  );
};

export default AgentWorkspace;

/**
 * User-facing support request hook.
 * Used in the Settings page Support tab.
 */

import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import { useAuth } from "@/contexts/AuthContext";
import { toast } from "sonner";
import type { SupportRequest, SupportPriority } from "@/hooks/admin/use-admin-support";

interface SubmitSupportRequestArgs {
  subject: string;
  message: string;
  priority: SupportPriority;
}

export function useSubmitSupportRequest() {
  const queryClient = useQueryClient();
  const { user } = useAuth();

  return useMutation({
    mutationFn: async ({ subject, message, priority }: SubmitSupportRequestArgs) => {
      if (!user) throw new Error("You must be logged in to submit a support request.");

      const { error } = await supabase.from("support_requests").insert({
        user_id: user.id,
        user_email: user.email ?? "",
        subject,
        message,
        priority,
        status: "open",
      });

      if (error) throw new Error(error.message);
    },
    onSuccess: () => {
      toast.success("Support request submitted. We'll get back to you soon.");
      queryClient.invalidateQueries({ queryKey: ["support-requests", "my"] });
    },
    onError: (error: Error) => {
      toast.error(`Failed to submit request: ${error.message}`);
    },
  });
}

export function useMySuportRequests() {
  const { user } = useAuth();

  return useQuery({
    queryKey: ["support-requests", "my", user?.id],
    queryFn: async () => {
      if (!user) return [] as SupportRequest[];

      const { data, error } = await supabase
        .from("support_requests")
        .select("id, subject, status, priority, created_at")
        .eq("user_id", user.id)
        .order("created_at", { ascending: false })
        .limit(10);

      if (error) throw new Error(error.message);
      return (data ?? []) as Pick<SupportRequest, "id" | "subject" | "status" | "priority" | "created_at">[];
    },
    enabled: !!user,
    staleTime: 60_000,
  });
}

