import { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import {
  User,
  Camera,
  CreditCard,
  Bell,
  Key,
  AlertTriangle,
  Trash2,
  Download,
  ExternalLink,
  Loader2,
  TrendingUp,
  Eye,
  EyeOff,
  Check,
  X,
  Zap,
  LifeBuoy,
  Send,
} from "lucide-react";
import supabase from "@/lib/supabase";
import { MIN_PASSWORD_LENGTH } from "@/lib/constants";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import {
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
} from "@/components/ui/tabs";
import { PageHeader } from "@/components/shared/PageHeader";
import { PremiumLock } from "@/components/shared/PremiumLock";
import { PageTransition } from "@/components/shared/PageTransition";
import { useAuth } from "@/contexts/AuthContext";
import { useUpdateProfile } from "@/hooks/use-profile";
import { useCustomerPortal, useUsage } from "@/hooks/use-billing";
import { useSubmitSupportRequest, useMySupportRequests } from "@/hooks/use-support";
import { toast } from "sonner";
import { cn } from "@/lib/utils";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import type { SupportPriority } from "@/hooks/admin/use-admin-support";

const NOTIF_STORAGE_KEY = "crobot_notifications";

const SettingsPage = () => {
  const navigate = useNavigate();
  const { profile, loading: authLoading } = useAuth();
  const updateProfile = useUpdateProfile();
  const portal = useCustomerPortal();
  const usage = useUsage();

  // Form state — controlled inputs for profile fields
  const [fullName, setFullName] = useState("");
  const [companyName, setCompanyName] = useState("");
  const [websiteUrl, setWebsiteUrl] = useState("");
  const [showPasswordChange, setShowPasswordChange] = useState(false);

  // Password change fields
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [showNewPassword, setShowNewPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [passwordUpdating, setPasswordUpdating] = useState(false);

  // Populate form once profile loads
  const seeded = useRef(false);
  useEffect(() => {
    if (profile && !seeded.current) {
      setFullName(profile.full_name ?? "");
      setCompanyName(profile.company_name ?? "");
      setWebsiteUrl(profile.website_url ?? "");
      seeded.current = true;
    }
  }, [profile]);

  // Persist notification prefs to localStorage
  const [notifications, setNotifications] = useState(() => {
    try {
      const stored = localStorage.getItem(NOTIF_STORAGE_KEY);
      if (stored) return JSON.parse(stored) as Record<string, boolean>;
    } catch { /* ignore */ }
    return {
      scanComplete: true,
      weeklyDigest: false,
      scoreDropAlert: true,
      productUpdates: true,
      marketing: false,
    };
  });

  useEffect(() => {
    localStorage.setItem(NOTIF_STORAGE_KEY, JSON.stringify(notifications));
  }, [notifications]);

  const handlePasswordChange = async () => {
    if (!newPassword) {
      toast.error("New password is required.");
      return;
    }
    if (newPassword.length < MIN_PASSWORD_LENGTH) {
      toast.error("Password must be at least 8 characters.");
      return;
    }
    if (newPassword !== confirmPassword) {
      toast.error("Passwords do not match.");
      return;
    }

    setPasswordUpdating(true);

    const { error } = await supabase.auth.updateUser({ password: newPassword });

    setPasswordUpdating(false);

    if (error) {
      toast.error(error.message ?? "Failed to update password. Please try again.");
      return;
    }

    toast.success("Password updated successfully.");
    setNewPassword("");
    setConfirmPassword("");
    setShowPasswordChange(false);
  };

  const handleSave = () => {
    updateProfile.mutate(
      {
        full_name: fullName.trim() || undefined,
        company_name: companyName.trim() || null,
        website_url: websiteUrl.trim() || null,
      },
      {
        onSuccess: () => toast.success("Profile saved"),
        onError: () => toast.error("Failed to save profile"),
      }
    );
  };

  if (authLoading || !profile) {
    return (
      <PageTransition>
        <div className="space-y-6">
          <div className="space-y-2">
            <Skeleton className="h-7 w-32" />
            <Skeleton className="h-4 w-64" />
          </div>
          <Skeleton className="h-12 w-80" />
          <Skeleton className="h-96" />
        </div>
      </PageTransition>
    );
  }

  const initials = profile.full_name?.split(" ").map((n) => n[0]).join("") ?? "?";
  const cycleEnd = profile.billing_cycle_end
    ? new Date(profile.billing_cycle_end).toLocaleDateString("en-US", {
        month: "long",
        day: "numeric",
        year: "numeric",
      })
    : "N/A";

  return (
    <PageTransition>
      <div className="space-y-6">
        <PageHeader title="Settings" description="Manage your account, billing, and preferences" />

        <Tabs defaultValue="profile" className="space-y-6">
          <TabsList className="bg-transparent p-0 h-auto gap-1 flex-wrap">
            {[
              { value: "profile", icon: User, label: "Profile" },
              { value: "billing", icon: CreditCard, label: "Billing" },
              { value: "notifications", icon: Bell, label: "Notifications" },
              { value: "api", icon: Key, label: "API Keys" },
              { value: "support", icon: LifeBuoy, label: "Support" },
            ].map((tab) => (
              <TabsTrigger
                key={tab.value}
                value={tab.value}
                className="rounded-lg border border-transparent px-4 py-2 text-sm data-[state=active]:border-border/60 data-[state=active]:bg-white data-[state=active]:shadow-sm"
              >
                <tab.icon className="mr-2 h-4 w-4" /> {tab.label}
              </TabsTrigger>
            ))}
          </TabsList>

          {/* ── Profile ────────────────────────────────────────── */}
          <TabsContent value="profile" className="space-y-6">
            <Card className="border-border/50 shadow-soft">
              <CardHeader>
                <CardTitle className="text-base">Profile information</CardTitle>
                <CardDescription>This is how you appear in shared reports and team settings</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                <div className="flex items-center gap-4">
                  <div className="group relative cursor-pointer">
                    <Avatar className="h-16 w-16">
                      <AvatarFallback className="bg-primary/8 text-primary text-xl font-bold">
                        {initials}
                      </AvatarFallback>
                    </Avatar>
                    <div className="absolute inset-0 flex items-center justify-center rounded-full bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity">
                      <Camera className="h-5 w-5 text-white" />
                    </div>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-foreground">{profile.full_name}</p>
                    <p className="text-xs text-muted-foreground">{profile.email}</p>
                    <Badge variant="outline" className="mt-1 text-2xs capitalize">{profile.plan} plan</Badge>
                  </div>
                </div>
                <Separator />
                <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                  <div className="space-y-2">
                    <Label htmlFor="s-name">Full name</Label>
                    <Input
                      id="s-name"
                      value={fullName}
                      onChange={(e) => setFullName(e.target.value)}
                      className="border-border/50"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-email">Email</Label>
                    <Input
                      id="s-email"
                      defaultValue={profile.email}
                      disabled
                      className="border-border/50 bg-muted/40"
                    />
                    <p className="text-xs text-muted-foreground">Contact support to change your email</p>
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-company">Company</Label>
                    <Input
                      id="s-company"
                      value={companyName}
                      onChange={(e) => setCompanyName(e.target.value)}
                      placeholder="Your company"
                      className="border-border/50"
                    />
                  </div>
                  <div className="space-y-2">
                    <Label htmlFor="s-website">Website</Label>
                    <Input
                      id="s-website"
                      value={websiteUrl}
                      onChange={(e) => setWebsiteUrl(e.target.value)}
                      placeholder="https://your-website.com"
                      className="border-border/50"
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <Label>Password</Label>
                  {showPasswordChange ? (
                    <div className="space-y-3 rounded-lg border border-border/50 p-4">
                      <div className="space-y-2">
                        <Label htmlFor="s-new-pw" className="text-xs">New password</Label>
                        <div className="relative">
                          <Input
                            id="s-new-pw"
                            type={showNewPassword ? "text" : "password"}
                            placeholder="Enter new password (min. 8 characters)"
                            value={newPassword}
                            onChange={(e) => setNewPassword(e.target.value)}
                            className="border-border/50 pr-10"
                            disabled={passwordUpdating}
                          />
                          <button
                            type="button"
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                            onClick={() => setShowNewPassword((v) => !v)}
                            aria-label={showNewPassword ? "Hide password" : "Show password"}
                            tabIndex={-1}
                          >
                            {showNewPassword ? (
                              <EyeOff className="h-4 w-4" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </button>
                        </div>
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="s-confirm-pw" className="text-xs">Confirm new password</Label>
                        <div className="relative">
                          <Input
                            id="s-confirm-pw"
                            type={showConfirmPassword ? "text" : "password"}
                            placeholder="Confirm new password"
                            value={confirmPassword}
                            onChange={(e) => setConfirmPassword(e.target.value)}
                            className="border-border/50 pr-10"
                            disabled={passwordUpdating}
                          />
                          <button
                            type="button"
                            className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
                            onClick={() => setShowConfirmPassword((v) => !v)}
                            aria-label={showConfirmPassword ? "Hide password" : "Show password"}
                            tabIndex={-1}
                          >
                            {showConfirmPassword ? (
                              <EyeOff className="h-4 w-4" />
                            ) : (
                              <Eye className="h-4 w-4" />
                            )}
                          </button>
                        </div>
                      </div>
                      <div className="flex gap-2">
                        <Button
                          size="sm"
                          disabled={passwordUpdating}
                          onClick={handlePasswordChange}
                        >
                          {passwordUpdating ? (
                            <><Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />Updating…</>
                          ) : (
                            "Update password"
                          )}
                        </Button>
                        <Button
                          size="sm"
                          variant="ghost"
                          disabled={passwordUpdating}
                          onClick={() => {
                            setShowPasswordChange(false);
                            setNewPassword("");
                            setConfirmPassword("");
                          }}
                        >
                          Cancel
                        </Button>
                      </div>
                    </div>
                  ) : (
                    <div className="flex gap-2">
                      <Input
                        type="password"
                        defaultValue="placeholder"
                        disabled
                        className="flex-1 border-border/50 bg-muted/40"
                        aria-label="Current password placeholder"
                      />
                      <Button
                        variant="outline"
                        className="border-border/50 shrink-0"
                        onClick={() => setShowPasswordChange(true)}
                      >
                        Change password
                      </Button>
                    </div>
                  )}
                </div>
                <Button onClick={handleSave} disabled={updateProfile.isPending}>
                  {updateProfile.isPending ? (
                    <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Saving...</>
                  ) : (
                    "Save changes"
                  )}
                </Button>
              </CardContent>
            </Card>

            {/* Danger zone */}
            <Card className="border-red-200/60 shadow-none">
              <CardHeader>
                <CardTitle className="text-base text-red-600 flex items-center gap-2">
                  <AlertTriangle className="h-4 w-4" />
                  Danger zone
                </CardTitle>
              </CardHeader>
              <CardContent className="space-y-4">
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-foreground">Export all data</p>
                    <p className="text-xs text-muted-foreground">Download all your scans and reports as a ZIP file</p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="border-border/50"
                    onClick={() => window.alert("Data export will download a ZIP file containing all your scans and reports. This feature is coming soon.")}
                  >
                    <Download className="mr-1.5 h-3.5 w-3.5" />
                    Export
                  </Button>
                </div>
                <Separator />
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-medium text-red-600">Delete account</p>
                    <p className="text-xs text-muted-foreground">Permanently delete your account and all associated data. This action cannot be undone.</p>
                  </div>
                  <Button
                    variant="outline"
                    size="sm"
                    className="border-red-200 text-red-600 hover:bg-red-50/50 hover:text-red-700"
                    onClick={() => {
                      if (window.confirm("Are you sure you want to delete your account? This will permanently remove all your scans, reports, and settings. This action cannot be undone.")) {
                        window.alert("Account deletion requires email confirmation. Check your inbox.");
                      }
                    }}
                  >
                    <Trash2 className="mr-1.5 h-3.5 w-3.5" />
                    Delete
                  </Button>
                </div>
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── Billing ────────────────────────────────────────── */}
          <TabsContent value="billing" className="space-y-6">
            {/* Current plan card */}
            <Card className="overflow-hidden border-2 border-slate-200 shadow-soft bg-gradient-to-br from-slate-50 to-white">
              <CardContent className="p-6 space-y-5">
                <div className="flex items-start justify-between gap-4">
                  <div>
                    <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground mb-1">
                      Current Plan
                    </p>
                    <div className="flex items-center gap-2">
                      <h3 className="text-2xl font-bold text-foreground capitalize">
                        {profile.plan}
                      </h3>
                      <Badge
                        className={cn(
                          "text-xs font-semibold px-2.5 py-0.5 uppercase",
                          profile.plan === "agency"
                            ? "bg-violet-100 text-violet-700 border-violet-200"
                            : profile.plan === "pro"
                            ? "bg-indigo-100 text-indigo-700 border-indigo-200"
                            : "bg-slate-100 text-slate-600 border-slate-200"
                        )}
                        variant="outline"
                      >
                        {profile.plan === "pro" && <Zap className="mr-1 h-2.5 w-2.5" />}
                        {profile.plan.toUpperCase()}
                      </Badge>
                    </div>
                    {profile.plan !== "free" && (
                      <p className="mt-1 text-xs text-muted-foreground">
                        {usage.billingCycleEnd
                          ? `Renews on ${cycleEnd}`
                          : "Active subscription"}
                      </p>
                    )}
                  </div>
                  {profile.plan !== "free" && (
                    <Button
                      variant="outline"
                      size="sm"
                      className="shrink-0 border-border/50"
                      disabled={portal.isPending}
                      onClick={() => portal.mutate()}
                    >
                      {portal.isPending ? (
                        <><Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />Opening...</>
                      ) : (
                        <>
                          <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                          Manage Billing
                        </>
                      )}
                    </Button>
                  )}
                </div>

                {/* Usage bar */}
                <div className="space-y-2">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-muted-foreground">Scans used this month</span>
                    <span className="text-sm font-semibold tabular-nums text-foreground">
                      {usage.scansUsed} / {usage.scanLimit}
                    </span>
                  </div>
                  <Progress
                    value={usage.usagePercent}
                    className={cn(
                      "h-2",
                      usage.usagePercent >= 100 && "[&>div]:bg-red-500",
                      usage.usagePercent >= 70 && usage.usagePercent < 100 && "[&>div]:bg-amber-500"
                    )}
                  />
                  <p className="text-xs text-muted-foreground">
                    {usage.billingCycleEnd
                      ? `Resets on ${cycleEnd}`
                      : "Resets at the start of each calendar month"}
                  </p>
                </div>

                {profile.plan === "free" && (
                  <Button
                    className="w-full rounded-lg font-semibold"
                    onClick={() => navigate("/pricing")}
                  >
                    <TrendingUp className="mr-2 h-4 w-4" />
                    Upgrade to Pro — $49/month
                  </Button>
                )}
              </CardContent>
            </Card>

            {/* Plan comparison — only for free users */}
            {profile.plan === "free" && (
              <Card className="border-border/50 shadow-soft">
                <CardHeader>
                  <CardTitle className="text-base">Plan comparison</CardTitle>
                  <CardDescription>See what you unlock with Pro or Agency</CardDescription>
                </CardHeader>
                <CardContent>
                  <div className="overflow-x-auto">
                    <table className="w-full min-w-[480px] text-sm">
                      <thead>
                        <tr className="border-b border-border/50">
                          <th className="pb-3 text-left text-xs font-medium text-muted-foreground">Feature</th>
                          <th className="pb-3 text-center text-xs font-semibold text-slate-600 w-24">Free</th>
                          <th className="pb-3 text-center text-xs font-semibold text-indigo-600 w-24">Pro</th>
                          <th className="pb-3 text-center text-xs font-medium text-muted-foreground w-24">Agency</th>
                        </tr>
                      </thead>
                      <tbody className="divide-y divide-border/30">
                        {[
                          { label: "Scans / month", free: "3", pro: "25", agency: "500" },
                          { label: "AI suggestions", free: false, pro: true, agency: true },
                          { label: "AI copy rewrites", free: false, pro: true, agency: true },
                          { label: "PDF report export", free: false, pro: true, agency: true },
                          { label: "Score monitoring", free: false, pro: true, agency: true },
                          { label: "Integrations", free: false, pro: false, agency: true },
                          { label: "White-label reports", free: false, pro: false, agency: true },
                          { label: "API access", free: false, pro: false, agency: true },
                        ].map((row) => (
                          <tr key={row.label}>
                            <td className="py-2.5 text-xs text-foreground/80">{row.label}</td>
                            {[row.free, row.pro, row.agency].map((val, i) => (
                              <td key={i} className="py-2.5 text-center">
                                {val === true ? (
                                  <Check className="mx-auto h-4 w-4 text-green-500" />
                                ) : val === false ? (
                                  <X className="mx-auto h-4 w-4 text-muted-foreground/30" />
                                ) : (
                                  <span className={cn("text-xs", i === 1 && "font-semibold text-indigo-600")}>
                                    {val}
                                  </span>
                                )}
                              </td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                  <Button
                    className="mt-4 w-full rounded-lg"
                    onClick={() => navigate("/pricing")}
                  >
                    View all plans
                  </Button>
                </CardContent>
              </Card>
            )}

            {/* Billing history */}
            <Card className="border-border/50 shadow-soft">
              <CardHeader>
                <div className="flex items-center justify-between">
                  <CardTitle className="text-base">Billing history</CardTitle>
                  {profile.plan !== "free" && (
                    <Button
                      variant="ghost"
                      size="sm"
                      className="text-xs text-muted-foreground"
                      disabled={portal.isPending}
                      onClick={() => portal.mutate()}
                    >
                      {portal.isPending ? (
                        <Loader2 className="h-3.5 w-3.5 animate-spin" />
                      ) : (
                        <>
                          <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                          View all invoices
                        </>
                      )}
                    </Button>
                  )}
                </div>
              </CardHeader>
              <CardContent>
                {profile.plan === "free" ? (
                  <div className="rounded-lg border border-dashed border-border/50 p-8 text-center">
                    <CreditCard className="mx-auto mb-3 h-8 w-8 text-muted-foreground/40" />
                    <p className="text-sm font-medium text-foreground">No billing history yet</p>
                    <p className="mt-1 text-xs text-muted-foreground">
                      Invoices will appear here once you upgrade to a paid plan
                    </p>
                    <Button
                      size="sm"
                      variant="outline"
                      className="mt-4 border-border/50"
                      onClick={() => navigate("/pricing")}
                    >
                      View plans
                    </Button>
                  </div>
                ) : (
                  <div className="rounded-lg border border-dashed border-border/50 p-8 text-center">
                    <p className="text-sm text-muted-foreground">
                      View and download invoices in the billing portal
                    </p>
                    <Button
                      size="sm"
                      variant="outline"
                      className="mt-4 border-border/50"
                      disabled={portal.isPending}
                      onClick={() => portal.mutate()}
                    >
                      {portal.isPending ? (
                        <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Opening...</>
                      ) : (
                        <>
                          <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                          Open billing portal
                        </>
                      )}
                    </Button>
                  </div>
                )}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── Notifications ──────────────────────────────────── */}
          <TabsContent value="notifications">
            <Card className="border-border/50 shadow-soft">
              <CardHeader>
                <CardTitle className="text-base">Email notifications</CardTitle>
                <CardDescription>Choose which emails you want to receive</CardDescription>
              </CardHeader>
              <CardContent className="space-y-6">
                {[
                  { key: "scanComplete" as const, label: "Scan completed", desc: "Email when a page analysis finishes" },
                  { key: "scoreDropAlert" as const, label: "Score drop alerts", desc: "Alert when a monitored page's score drops by more than 10 points" },
                  { key: "weeklyDigest" as const, label: "Weekly CRO digest", desc: "Summary of your page scores and improvement opportunities" },
                  { key: "productUpdates" as const, label: "Product updates", desc: "New features, pillar additions, and integration launches" },
                  { key: "marketing" as const, label: "CRO tips & resources", desc: "Conversion optimization tips, case studies, and industry data" },
                ].map((item) => (
                  <div key={item.key} className="flex items-center justify-between">
                    <div>
                      <p className="text-sm font-medium text-foreground">{item.label}</p>
                      <p className="text-xs text-muted-foreground">{item.desc}</p>
                    </div>
                    <Switch
                      checked={!!notifications[item.key]}
                      onCheckedChange={(checked) =>
                        setNotifications((prev) => ({ ...prev, [item.key]: checked }))
                      }
                    />
                  </div>
                ))}
              </CardContent>
            </Card>
          </TabsContent>

          {/* ── API Keys ───────────────────────────────────────── */}
          <TabsContent value="api">
            <PremiumLock message="REST API access is available on the Agency plan ($199/mo)">
              <Card className="border-border/50 shadow-soft">
                <CardHeader>
                  <CardTitle className="text-base">API keys</CardTitle>
                  <CardDescription>Use the REST API to run scans programmatically and integrate with your workflow</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                  <div className="flex items-center gap-3 rounded-lg bg-muted/40 p-4 font-mono">
                    <code className="flex-1 text-sm text-slate-600 select-all">sk_live_cRoBoT_••••••••••••••••••••</code>
                    <Button variant="outline" size="sm" onClick={() => window.alert("Reveal requires Agency plan authentication.")}>Reveal</Button>
                    <Button variant="outline" size="sm" onClick={() => { navigator.clipboard.writeText("sk_live_cRoBoT_demo_key"); window.alert("API key copied to clipboard."); }}>Copy</Button>
                  </div>
                  <div className="flex gap-2">
                    <Button onClick={() => window.alert("New API key generated. Your previous key has been revoked.")}>Generate new key</Button>
                    <Button variant="outline" className="border-border/50" onClick={() => window.open("https://docs.crobot.app/api", "_blank")}>
                      <ExternalLink className="mr-1.5 h-3.5 w-3.5" />
                      View API docs
                    </Button>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Rate limit: 100,000 API calls/month &middot; Keys are scoped to your account &middot; Rotate keys every 90 days
                  </p>
                </CardContent>
              </Card>
            </PremiumLock>
          </TabsContent>

          {/* ── Support ────────────────────────────────────────── */}
          <TabsContent value="support" className="space-y-6">
            <SupportTab />
          </TabsContent>
        </Tabs>
      </div>
    </PageTransition>
  );
};

// ── Support tab sub-component ─────────────────────────────────

const STATUS_BADGE_CLASSES: Record<string, string> = {
  open: "bg-amber-100 text-amber-700",
  in_progress: "bg-blue-100 text-blue-700",
  resolved: "bg-green-100 text-green-700",
  closed: "bg-slate-100 text-slate-600",
};

function SupportTab() {
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  const [priority, setPriority] = useState<SupportPriority>("normal");
  const [subjectError, setSubjectError] = useState<string | null>(null);
  const [messageError, setMessageError] = useState<string | null>(null);

  const submitRequest = useSubmitSupportRequest();
  const myRequests = useMySuportRequests();

  const handleSubmit = () => {
    let valid = true;
    if (!subject.trim()) {
      setSubjectError("Subject is required.");
      valid = false;
    } else if (subject.length > 100) {
      setSubjectError("Subject must be 100 characters or less.");
      valid = false;
    } else {
      setSubjectError(null);
    }

    if (!message.trim()) {
      setMessageError("Message is required.");
      valid = false;
    } else if (message.length < 20) {
      setMessageError("Message must be at least 20 characters.");
      valid = false;
    } else if (message.length > 2000) {
      setMessageError("Message must be 2000 characters or less.");
      valid = false;
    } else {
      setMessageError(null);
    }

    if (!valid) return;

    submitRequest.mutate(
      { subject: subject.trim(), message: message.trim(), priority },
      {
        onSuccess: () => {
          setSubject("");
          setMessage("");
          setPriority("normal");
        },
      }
    );
  };

  return (
    <div className="space-y-6">
      {/* Submit form */}
      <Card className="border-border/50 shadow-soft">
        <CardHeader>
          <CardTitle className="text-base">Contact Support</CardTitle>
          <CardDescription>
            Submit a support request and our team will get back to you.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Subject */}
          <div className="space-y-1.5">
            <Label htmlFor="support-subject">Subject</Label>
            <Input
              id="support-subject"
              value={subject}
              onChange={(e) => { setSubject(e.target.value); setSubjectError(null); }}
              placeholder="Brief description of your issue..."
              maxLength={100}
              className={cn("border-border/50", subjectError && "border-red-500")}
            />
            {subjectError && (
              <p className="text-xs text-red-600">{subjectError}</p>
            )}
          </div>

          {/* Priority */}
          <div className="space-y-1.5">
            <Label htmlFor="support-priority">Priority</Label>
            <Select value={priority} onValueChange={(v) => setPriority(v as SupportPriority)}>
              <SelectTrigger id="support-priority" className="border-border/50">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="normal">Normal</SelectItem>
                <SelectItem value="high">High</SelectItem>
                <SelectItem value="urgent">Urgent</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Message */}
          <div className="space-y-1.5">
            <Label htmlFor="support-message">
              Message
              <span className="ml-2 text-xs font-normal text-muted-foreground">
                ({message.length}/2000)
              </span>
            </Label>
            <Textarea
              id="support-message"
              value={message}
              onChange={(e) => { setMessage(e.target.value); setMessageError(null); }}
              placeholder="Describe your issue in detail..."
              maxLength={2000}
              className={cn("min-h-[120px] resize-none border-border/50", messageError && "border-red-500")}
            />
            {messageError && (
              <p className="text-xs text-red-600">{messageError}</p>
            )}
          </div>

          <Button
            onClick={handleSubmit}
            disabled={submitRequest.isPending}
            className="w-full sm:w-auto"
          >
            {submitRequest.isPending ? (
              <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
            ) : (
              <Send className="mr-2 h-3.5 w-3.5" />
            )}
            {submitRequest.isPending ? "Submitting…" : "Submit Request"}
          </Button>
        </CardContent>
      </Card>

      {/* My past requests */}
      <Card className="border-border/50 shadow-soft">
        <CardHeader>
          <CardTitle className="text-base">My Support Requests</CardTitle>
          <CardDescription>
            Track the status of your submitted requests.
          </CardDescription>
        </CardHeader>
        <CardContent>
          {myRequests.isLoading ? (
            <div className="space-y-2">
              {Array.from({ length: 3 }).map((_, i) => (
                <Skeleton key={i} className="h-10 w-full rounded-lg" />
              ))}
            </div>
          ) : !myRequests.data || myRequests.data.length === 0 ? (
            <div className="rounded-xl border border-dashed border-border/50 py-8 text-center">
              <LifeBuoy className="mx-auto h-8 w-8 text-muted-foreground/40 mb-2" />
              <p className="text-sm text-muted-foreground">No support requests yet.</p>
            </div>
          ) : (
            <div className="rounded-xl border border-border/50 overflow-hidden">
              <Table>
                <TableHeader>
                  <TableRow className="bg-muted/40 hover:bg-muted/40">
                    <TableHead>Subject</TableHead>
                    <TableHead>Priority</TableHead>
                    <TableHead>Status</TableHead>
                    <TableHead>Submitted</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {myRequests.data.map((req) => (
                    <TableRow key={req.id}>
                      <TableCell className="text-sm font-medium max-w-[200px]">
                        <span className="truncate block">{req.subject}</span>
                      </TableCell>
                      <TableCell>
                        <Badge className={`text-2xs px-1.5 py-0 capitalize bg-muted/50 text-foreground/70 border-0`}>
                          {req.priority}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <Badge className={`text-2xs px-1.5 py-0 border-0 ${STATUS_BADGE_CLASSES[req.status] ?? "bg-muted/50 text-foreground/70"}`}>
                          {req.status.replace("_", " ")}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                        {new Date(req.created_at).toLocaleDateString("en-US", {
                          month: "short",
                          day: "numeric",
                          year: "numeric",
                        })}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export default SettingsPage;

