import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Check, X, Zap, Shield, HelpCircle, Loader2 } from "lucide-react";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Accordion,
  AccordionContent,
  AccordionItem,
  AccordionTrigger,
} from "@/components/ui/accordion";
import { PageTransition } from "@/components/shared/PageTransition";
import { PRICING_TIERS } from "@/lib/constants";
import { useAuth } from "@/contexts/AuthContext";
import { useCheckout, useCustomerPortal } from "@/hooks/use-billing";
import type { PlanType } from "@/types";
import { cn } from "@/lib/utils";

const FAQ_ITEMS = [
  {
    q: "What happens when my 14-day trial ends?",
    a: "Your account automatically switches to the Free plan (3 scans/month). You won't be charged unless you explicitly upgrade. All your existing reports remain accessible — we never delete your data.",
  },
  {
    q: "What exactly counts as one scan?",
    a: "One scan = one URL analyzed on one device type. Scanning example.com/pricing on desktop counts as 1 scan. If you scan the same URL again (to check improvements), that counts as another scan. Re-scans from the report page also count.",
  },
  {
    q: "How is the CRO score calculated?",
    a: "Each of the 7 CRO pillars is scored 0-100 based on specific automated checks (contrast ratios, element positioning, page speed metrics, etc.). Pillar weights vary by page type — for example, CTA Effectiveness is weighted 22% on landing pages but only 12% on blog posts. Your overall score is the weighted average.",
  },
  {
    q: "Can I switch between monthly and annual billing?",
    a: "Yes. Switch anytime from Settings → Billing. When switching from monthly to annual, we prorate the remaining days on your current cycle as a credit. When switching from annual to monthly, the change takes effect at your next renewal date.",
  },
  {
    q: "Do you offer refunds?",
    a: "Yes — 30-day money-back guarantee, no questions asked. If the tool doesn't deliver actionable insights for your specific pages, we'll refund your payment in full. Email support@crobot.app to request a refund.",
  },
  {
    q: "Is my website data secure?",
    a: "We take screenshots and scrape publicly visible page content — the same information any visitor to your site would see. We don't access your CMS, analytics, or any private data. All data is encrypted (TLS 1.3 in transit, AES-256 at rest) and stored on SOC 2 compliant infrastructure.",
  },
];

const COMPARISON_ROWS = [
  { feature: "Page scans per month", free: "3", pro: "50", agency: "500" },
  { feature: "CRO pillars analyzed", free: "7", pro: "7", agency: "7" },
  { feature: "Suggestions per scan", free: "Top 3 only", pro: "All", agency: "All" },
  { feature: "AI copy rewrites", free: false, pro: true, agency: true },
  { feature: "PDF report export", free: false, pro: true, agency: true },
  { feature: "Monthly score monitoring", free: false, pro: true, agency: true },
  { feature: "Industry benchmark comparison", free: false, pro: true, agency: true },
  { feature: "Analytics integrations", free: false, pro: false, agency: true },
  { feature: "White-label reports", free: false, pro: false, agency: true },
  { feature: "REST API access", free: false, pro: false, agency: "100K calls/mo" },
  { feature: "Team members", free: "1", pro: "3", agency: "Unlimited" },
  { feature: "Support response time", free: "48 hours", pro: "12 hours", agency: "< 2 hours" },
];

// Resolve the CTA label based on current plan vs tier
function getCtaLabel(
  tierPlan: PlanType,
  currentPlan: PlanType | null,
  defaultLabel: string
): string {
  if (!currentPlan) return defaultLabel;
  if (currentPlan === tierPlan) return "Current Plan";
  if (tierPlan === "free") return "Downgrade to Free";

  const planOrder: PlanType[] = ["free", "pro", "agency"];
  const currentIndex = planOrder.indexOf(currentPlan);
  const tierIndex = planOrder.indexOf(tierPlan);

  if (tierIndex > currentIndex) return `Upgrade to ${tierPlan === "pro" ? "Pro" : "Agency"}`;
  return `Switch to ${tierPlan === "pro" ? "Pro" : "Agency"}`;
}

const Pricing = () => {
  const [isAnnual, setIsAnnual] = useState(false);
  const navigate = useNavigate();
  const { profile } = useAuth();
  const checkout = useCheckout();
  const portal = useCustomerPortal();

  const currentPlan = profile?.plan ?? null;
  const billingCycle = isAnnual ? "annual" : "monthly";

  function handleCta(tierPlan: PlanType) {
    if (!profile) {
      // Not logged in — send to signup
      navigate("/auth");
      return;
    }

    if (tierPlan === "free") {
      // Downgrading to free — send to portal to cancel
      portal.mutate();
      return;
    }

    if (tierPlan === currentPlan) {
      // Already on this plan — send to portal to manage
      portal.mutate();
      return;
    }

    // Upgrade or switch plan
    checkout.mutate({
      plan: tierPlan as Exclude<PlanType, "free">,
      billingCycle,
    });
  }

  return (
    <PageTransition>
      <div className="space-y-12">
        {/* Header */}
        <div className="text-center">
          <h2 className="text-xl font-semibold tracking-tight text-foreground">
            Pick the plan that fits your workflow
          </h2>
          <p className="mt-2 text-muted-foreground">
            Free to start. Upgrade when your page count grows. Cancel anytime.
          </p>

          <div className="mt-6 flex items-center justify-center gap-3">
            <Label htmlFor="billing-toggle" className={cn("text-sm", !isAnnual && "font-semibold text-foreground")}>
              Monthly
            </Label>
            <Switch id="billing-toggle" checked={isAnnual} onCheckedChange={setIsAnnual} />
            <Label htmlFor="billing-toggle" className={cn("text-sm", isAnnual && "font-semibold text-foreground")}>
              Annual
            </Label>
            {isAnnual && (
              <Badge className="bg-green-50 text-green-700 border-green-200 text-xs">
                Save 20%
              </Badge>
            )}
          </div>
        </div>

        {/* Pricing Cards */}
        <div className="mx-auto grid max-w-4xl grid-cols-1 gap-6 md:grid-cols-3">
          {PRICING_TIERS.map((tier) => {
            const price = isAnnual ? tier.price_annual : tier.price_monthly;
            const isCurrentPlan = currentPlan === tier.plan;
            const isPaidPlan = tier.plan !== "free";
            const isCheckoutPending =
              checkout.isPending &&
              checkout.variables?.plan === tier.plan;
            const isPortalPending =
              portal.isPending &&
              (isCurrentPlan || tier.plan === "free");

            const ctaLabel = profile
              ? getCtaLabel(tier.plan, currentPlan, tier.cta_text)
              : tier.cta_text;

            const isPending = isCheckoutPending || isPortalPending;

            return (
              <Card
                key={tier.plan}
                className={cn(
                  "relative border-border/50 shadow-soft transition-all",
                  tier.highlighted &&
                    "border-primary ring-2 ring-primary/20 sm:scale-[1.02] shadow-lg shadow-primary/10"
                )}
              >
                {tier.highlighted && (
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                    <Badge className="bg-primary text-primary-foreground px-3 py-1 text-xs font-semibold">
                      <Zap className="mr-1 h-3 w-3" />
                      Most Popular
                    </Badge>
                  </div>
                )}
                {isCurrentPlan && (
                  <div className="absolute -top-3 left-1/2 -translate-x-1/2">
                    <Badge variant="outline" className="bg-card px-3 py-1 text-xs font-semibold border-border">
                      Your Plan
                    </Badge>
                  </div>
                )}
                <CardHeader className="text-center pb-2 pt-8">
                  <CardTitle className={cn("text-lg font-semibold", tier.highlighted ? "text-primary" : "text-foreground")}>
                    {tier.name}
                  </CardTitle>
                  <CardDescription className="text-sm">{tier.subtitle}</CardDescription>
                </CardHeader>
                <CardContent className="text-center">
                  <div className="mb-1">
                    <span className="text-4xl font-semibold leading-none text-foreground tabular-nums">
                      ${price}
                    </span>
                    <span className="text-muted-foreground">/mo</span>
                  </div>
                  {isAnnual && tier.price_monthly > 0 && (
                    <p className="mb-4 text-xs text-muted-foreground">
                      Billed as ${price * 12}/year &middot; was ${tier.price_monthly * 12}/year
                    </p>
                  )}
                  {!isAnnual && <p className="mb-4 text-xs text-muted-foreground">{tier.limits}</p>}

                  {isCurrentPlan && isPaidPlan ? (
                    <Button
                      className="w-full rounded-lg"
                      variant="outline"
                      disabled={portal.isPending}
                      onClick={() => portal.mutate()}
                    >
                      {portal.isPending ? (
                        <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Opening portal...</>
                      ) : (
                        "Manage Subscription"
                      )}
                    </Button>
                  ) : (
                    <Button
                      className={cn("w-full rounded-lg", !tier.highlighted && "bg-card border border-border/50 text-foreground hover:bg-muted/50")}
                      variant={tier.highlighted ? "default" : "outline"}
                      disabled={isPending || isCurrentPlan}
                      onClick={() => handleCta(tier.plan)}
                    >
                      {isPending ? (
                        <><Loader2 className="mr-2 h-4 w-4 animate-spin" />Redirecting...</>
                      ) : (
                        ctaLabel
                      )}
                    </Button>
                  )}

                  <ul className="mt-6 space-y-3 text-left">
                    <TooltipProvider delayDuration={300}>
                      {tier.features.map((feature, i) => (
                        <li key={i} className="flex items-start gap-2.5">
                          {feature.included ? (
                            <Check className="mt-0.5 h-4 w-4 shrink-0 text-green-500" />
                          ) : (
                            <X className="mt-0.5 h-4 w-4 shrink-0 text-muted-foreground/40" />
                          )}
                          <span className={cn("text-sm", feature.included ? "text-foreground" : "text-muted-foreground")}>
                            {feature.text}
                          </span>
                          {feature.tooltip && (
                            <Tooltip>
                              <TooltipTrigger asChild>
                                <HelpCircle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-muted-foreground/40 cursor-help" />
                              </TooltipTrigger>
                              <TooltipContent side="top"><p className="text-xs">{feature.tooltip}</p></TooltipContent>
                            </Tooltip>
                          )}
                        </li>
                      ))}
                    </TooltipProvider>
                  </ul>
                </CardContent>
              </Card>
            );
          })}
        </div>

        {/* Trust badges */}
        <div className="flex flex-wrap items-center justify-center gap-6 text-xs text-muted-foreground">
          {[
            { icon: Shield, text: "256-bit SSL encrypted" },
            { icon: Shield, text: "SOC 2 compliant infrastructure" },
            { icon: Shield, text: "GDPR compliant" },
            { icon: Shield, text: "30-day money-back guarantee" },
          ].map((badge) => (
            <span key={badge.text} className="flex items-center gap-1.5">
              <badge.icon className="h-3.5 w-3.5 text-muted-foreground" />
              {badge.text}
            </span>
          ))}
        </div>

        <Separator />

        {/* Feature Comparison Table */}
        <div className="mx-auto max-w-4xl">
          <h3 className="mb-6 text-center text-xl font-bold text-foreground">Feature comparison</h3>
          <div className="overflow-x-auto">
            <table className="w-full min-w-[600px] text-sm">
              <thead>
                <tr className="border-b border-border/50">
                  <th className="pb-3 text-left font-medium text-muted-foreground">Feature</th>
                  <th className="pb-3 text-center font-medium text-muted-foreground w-28">Free</th>
                  <th className="pb-3 text-center font-semibold text-primary w-28">Pro</th>
                  <th className="pb-3 text-center font-medium text-muted-foreground w-28">Agency</th>
                </tr>
              </thead>
              <tbody>
                {COMPARISON_ROWS.map((row) => (
                  <tr key={row.feature} className="border-b border-border/40">
                    <td className="py-3 text-foreground">{row.feature}</td>
                    {[row.free, row.pro, row.agency].map((val, i) => (
                      <td key={i} className="py-3 text-center">
                        {val === true ? (
                          <Check className="mx-auto h-4 w-4 text-green-500" />
                        ) : val === false ? (
                          <X className="mx-auto h-4 w-4 text-muted-foreground/40" />
                        ) : (
                          <span className={cn("text-xs", i === 1 ? "font-semibold text-primary" : "text-foreground/80")}>
                            {val}
                          </span>
                        )}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <Separator />

        {/* FAQ */}
        <div className="mx-auto max-w-2xl">
          <h3 className="mb-6 text-center text-xl font-bold text-foreground">
            Common questions
          </h3>
          <Accordion type="single" collapsible className="w-full">
            {FAQ_ITEMS.map((item, i) => (
              <AccordionItem key={i} value={`faq-${i}`}>
                <AccordionTrigger className="text-sm font-medium text-foreground hover:text-primary text-left">
                  {item.q}
                </AccordionTrigger>
                <AccordionContent className="text-sm text-muted-foreground leading-relaxed">
                  {item.a}
                </AccordionContent>
              </AccordionItem>
            ))}
          </Accordion>
        </div>
      </div>
    </PageTransition>
  );
};

export default Pricing;

