import { useState, useCallback } from "react";
import { useDebounce } from "@/hooks/use-debounce";
import {
  ScanLine,
  Search,
  ChevronLeft,
  ChevronRight,
  ExternalLink,
  Trash2,
  MoreHorizontal,
  AlertTriangle,
  CheckCircle2,
  Clock,
  Loader2,
  ChevronUp,
  ChevronDown,
  ChevronsUpDown,
  RotateCcw,
} from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { EmptyState } from "@/components/shared/EmptyState";
import { KpiCard } from "@/components/shared/KpiCard";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import {
  useAdminScans,
  useAdminScanStats,
  useDeleteScan,
  useAdminRetryScan,
  type AdminScansFilter,
} from "@/hooks/admin/use-admin-scans";
import type { ScanRow } from "@/types/database";
import type { ScanStatus } from "@/types/index";
import { format } from "date-fns";

// ── Constants ─────────────────────────────────────────────────

const PAGE_SIZE = 25;

const STATUS_OPTIONS: { value: ScanStatus | ""; label: string }[] = [
  { value: "", label: "All statuses" },
  { value: "pending", label: "Pending" },
  { value: "analyzing", label: "Analyzing" },
  { value: "completed", label: "Completed" },
  { value: "failed", label: "Failed" },
];

const STATUS_BADGE_CLASSES: Record<ScanStatus, string> = {
  completed: "bg-green-100 text-green-700 border-0",
  failed: "bg-red-100 text-red-700 border-0",
  pending: "bg-muted/50 text-foreground/80 border-0",
  analyzing: "bg-blue-100 text-blue-700 border-0",
};

const STATUS_ICONS: Record<ScanStatus, React.ElementType> = {
  completed: CheckCircle2,
  failed: AlertTriangle,
  pending: Clock,
  analyzing: Loader2,
};

type SortableColumn = "created_at" | "overall_score" | "issues_found" | "url" | "status";

// ── Sub-components ────────────────────────────────────────────

function StatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
      {Array.from({ length: 4 }).map((_, i) => (
        <Skeleton key={i} className="h-[120px] rounded-xl" />
      ))}
    </div>
  );
}

function TableSkeleton() {
  return (
    <>
      {Array.from({ length: 8 }).map((_, i) => (
        <TableRow key={i}>
          {Array.from({ length: 8 }).map((__, j) => (
            <TableCell key={j}>
              <Skeleton className="h-4 w-full max-w-[120px]" />
            </TableCell>
          ))}
        </TableRow>
      ))}
    </>
  );
}

function SortIcon({
  column,
  sortColumn,
  sortAsc,
}: {
  column: SortableColumn;
  sortColumn: SortableColumn;
  sortAsc: boolean;
}) {
  if (sortColumn !== column)
    return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-muted-foreground/40" />;
  return sortAsc ? (
    <ChevronUp className="ml-1 h-3.5 w-3.5 text-primary" />
  ) : (
    <ChevronDown className="ml-1 h-3.5 w-3.5 text-primary" />
  );
}

function ScoreDisplay({ score }: { score: number | null }) {
  if (score === null) return <span className="text-muted-foreground/50">—</span>;
  const color =
    score >= 75
      ? "text-green-600"
      : score >= 50
      ? "text-amber-600"
      : "text-red-600";
  return (
    <span className={`font-semibold tabular-nums ${color}`}>{score}</span>
  );
}

// ── SortableHeader ────────────────────────────────────────────

function SortableHeader({
  column,
  label,
  className,
  sortColumn,
  sortAsc,
  onSort,
}: {
  column: SortableColumn;
  label: string;
  className?: string;
  sortColumn: SortableColumn;
  sortAsc: boolean;
  onSort: (col: SortableColumn) => void;
}) {
  return (
    <TableHead
      className={`cursor-pointer select-none whitespace-nowrap ${className ?? ""}`}
      onClick={() => onSort(column)}
      aria-sort={
        sortColumn === column ? (sortAsc ? "ascending" : "descending") : "none"
      }
    >
      <span className="inline-flex items-center">
        {label}
        <SortIcon column={column} sortColumn={sortColumn} sortAsc={sortAsc} />
      </span>
    </TableHead>
  );
}

// ── Main page ─────────────────────────────────────────────────

export default function AdminScans() {
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState<ScanStatus | "">("");
  const [page, setPage] = useState(0);
  const [sortColumn, setSortColumn] = useState<SortableColumn>("created_at");
  const [sortAsc, setSortAsc] = useState(false);
  const [deleteTarget, setDeleteTarget] = useState<{ id: string; url: string } | null>(null);

  const debouncedSearch = useDebounce(search, 350);

  const filter: AdminScansFilter = {
    search: debouncedSearch || undefined,
    status: statusFilter || undefined,
  };

  const { data, isLoading, isError } = useAdminScans({
    page,
    pageSize: PAGE_SIZE,
    filter,
    sortColumn: sortColumn as keyof ScanRow,
    sortAsc,
  });

  const statsQuery = useAdminScanStats();
  const deleteScan = useDeleteScan();
  const retryScan = useAdminRetryScan();
  const [retryTarget, setRetryTarget] = useState<{ id: string; url: string } | null>(null);

  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;

  const handleSort = useCallback((col: SortableColumn) => {
    setSortColumn((prev) => {
      if (prev === col) {
        setSortAsc((asc) => !asc);
        return prev;
      }
      setSortAsc(true);
      return col;
    });
    setPage(0);
  }, []);

  const hasFilters = debouncedSearch || statusFilter;

  return (
    <div className="space-y-8">
      <PageHeader
        title="All Scans"
        description={
          data
            ? `${data.total.toLocaleString()} scans across all users`
            : "Platform-wide scan overview"
        }
      />

      {/* KPI row */}
      {statsQuery.isLoading ? (
        <StatsSkeleton />
      ) : statsQuery.isError ? (
        <div
          role="alert"
          className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700"
        >
          Failed to load scan stats.
        </div>
      ) : (
        <div className="grid grid-cols-2 gap-4 lg:grid-cols-4">
          <KpiCard
            title="Total Scans"
            value={statsQuery.data?.totalScans ?? 0}
            icon={ScanLine}
            iconColor="text-indigo-600"
            iconBg="bg-indigo-100"
          />
          <KpiCard
            title="Avg Score"
            value={statsQuery.data?.avgScore ?? 0}
            icon={CheckCircle2}
            iconColor="text-green-600"
            iconBg="bg-green-100"
            suffix="/100"
          />
          <KpiCard
            title="Failed Scans"
            value={statsQuery.data?.failedScans ?? 0}
            icon={AlertTriangle}
            iconColor="text-red-600"
            iconBg="bg-red-100"
          />
          <KpiCard
            title="Scans Today"
            value={statsQuery.data?.scansToday ?? 0}
            icon={Clock}
            iconColor="text-sky-600"
            iconBg="bg-sky-100"
          />
        </div>
      )}

      {/* Filters */}
      <div className="flex flex-wrap items-center gap-3">
        <div className="relative flex-1 min-w-[220px] max-w-xs">
          <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            placeholder="Search by URL or user email..."
            value={search}
            onChange={(e) => { setSearch(e.target.value); setPage(0); }}
            className="pl-9"
            aria-label="Search scans"
          />
        </div>

        <Select
          value={statusFilter}
          onValueChange={(v) => {
            setStatusFilter(v as ScanStatus | "");
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[150px]" aria-label="Filter by status">
            <SelectValue placeholder="All statuses" />
          </SelectTrigger>
          <SelectContent>
            {STATUS_OPTIONS.map((opt) => (
              <SelectItem key={opt.value} value={opt.value}>
                {opt.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>

        {hasFilters && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setSearch("");
              setStatusFilter("");
              setPage(0);
            }}
          >
            Clear filters
          </Button>
        )}
      </div>

      {/* Table */}
      <div className="rounded-xl border border-border/50 overflow-hidden overflow-x-auto scrollbar-thin">
        <Table>
          <TableHeader>
            <TableRow className="bg-muted/40 hover:bg-muted/40">
              <SortableHeader column="url" label="URL" className="max-w-[220px]" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <TableHead>User</TableHead>
              <SortableHeader column="overall_score" label="Score" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <SortableHeader column="status" label="Status" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <TableHead>Page Type</TableHead>
              <SortableHeader column="issues_found" label="Issues" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <SortableHeader column="created_at" label="Date" sortColumn={sortColumn} sortAsc={sortAsc} onSort={handleSort} />
              <TableHead className="w-10" />
            </TableRow>
          </TableHeader>
          <TableBody>
            {isLoading ? (
              <TableSkeleton />
            ) : isError ? (
              <TableRow>
                <TableCell
                  colSpan={8}
                  className="py-10 text-center text-sm text-red-600"
                >
                  Failed to load scans. Check your admin permissions.
                </TableCell>
              </TableRow>
            ) : data?.scans.length === 0 ? (
              <TableRow>
                <TableCell colSpan={8} className="p-0">
                  <EmptyState
                    icon={ScanLine}
                    title="No scans found"
                    description={
                      hasFilters
                        ? "Try adjusting your search or filters."
                        : "No scans have been run yet."
                    }
                  />
                </TableCell>
              </TableRow>
            ) : (
              data?.scans.map((scan) => {
                const StatusIcon = STATUS_ICONS[scan.status];
                return (
                  <TableRow
                    key={scan.id}
                    className="hover:bg-muted/40 transition-colors"
                  >
                    {/* URL */}
                    <TableCell className="max-w-[220px]">
                      <a
                        href={`/reports/${scan.id}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="flex items-center gap-1 font-mono text-xs text-muted-foreground hover:text-foreground transition-colors"
                        aria-label={`View report for ${scan.url}`}
                      >
                        <span className="truncate max-w-[180px]">
                          {scan.url.replace(/^https?:\/\//, "")}
                        </span>
                        <ExternalLink className="h-3 w-3 shrink-0" />
                      </a>
                    </TableCell>

                    {/* User */}
                    <TableCell>
                      <div className="text-xs">
                        <p className="font-medium text-foreground truncate max-w-[140px]">
                          {scan.user_name ?? scan.user_email ?? "—"}
                        </p>
                        {scan.user_name && (
                          <p className="text-muted-foreground font-mono truncate max-w-[140px]">
                            {scan.user_email}
                          </p>
                        )}
                      </div>
                    </TableCell>

                    {/* Score */}
                    <TableCell>
                      <ScoreDisplay score={scan.overall_score} />
                    </TableCell>

                    {/* Status */}
                    <TableCell>
                      <Badge
                        className={`inline-flex items-center gap-1 text-2xs px-1.5 py-0.5 capitalize ${
                          STATUS_BADGE_CLASSES[scan.status]
                        }`}
                      >
                        <StatusIcon className="h-2.5 w-2.5" />
                        {scan.status}
                      </Badge>
                    </TableCell>

                    {/* Page type */}
                    <TableCell className="text-xs text-muted-foreground capitalize">
                      {scan.page_type}
                    </TableCell>

                    {/* Issues */}
                    <TableCell className="text-sm text-muted-foreground">
                      {scan.issues_found > 0 ? (
                        <span className="font-medium text-foreground">
                          {scan.issues_found}
                        </span>
                      ) : (
                        "—"
                      )}
                    </TableCell>

                    {/* Date */}
                    <TableCell className="text-xs text-muted-foreground whitespace-nowrap">
                      {format(new Date(scan.created_at), "MMM d, yyyy")}
                    </TableCell>

                    {/* Actions */}
                    <TableCell>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-7 w-7"
                            aria-label="Scan actions"
                          >
                            <MoreHorizontal className="h-4 w-4" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end" className="w-40">
                          <DropdownMenuItem
                            onClick={() =>
                              window.open(`/reports/${scan.id}`, "_blank")
                            }
                          >
                            <ExternalLink className="mr-2 h-3.5 w-3.5" />
                            View Report
                          </DropdownMenuItem>
                          {scan.status === "failed" && (
                            <>
                              <DropdownMenuSeparator />
                              <DropdownMenuItem
                                onClick={() =>
                                  setRetryTarget({ id: scan.id, url: scan.url })
                                }
                                disabled={retryScan.isPending && retryScan.variables === scan.id}
                              >
                                {retryScan.isPending && retryScan.variables === scan.id ? (
                                  <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
                                ) : (
                                  <RotateCcw className="mr-2 h-3.5 w-3.5" />
                                )}
                                Retry Scan
                              </DropdownMenuItem>
                            </>
                          )}
                          <DropdownMenuSeparator />
                          <DropdownMenuItem
                            className="text-red-600"
                            onClick={() =>
                              setDeleteTarget({ id: scan.id, url: scan.url })
                            }
                          >
                            <Trash2 className="mr-2 h-3.5 w-3.5" />
                            Delete Scan
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between">
          <p className="text-sm text-muted-foreground">
            Page {page + 1} of {totalPages} ({data?.total.toLocaleString()}{" "}
            scans)
          </p>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={page >= totalPages - 1}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}

      {/* Retry confirm dialog */}
      <AlertDialog
        open={retryTarget !== null}
        onOpenChange={(open) => {
          if (!open) setRetryTarget(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Retry this scan?</AlertDialogTitle>
            <AlertDialogDescription>
              This will reset the scan status to{" "}
              <code className="font-mono text-xs bg-muted/50 px-1 py-0.5 rounded">
                pending
              </code>{" "}
              and re-queue the analysis for{" "}
              <span className="font-mono text-xs">
                {retryTarget?.url.replace(/^https?:\/\//, "").slice(0, 60)}
              </span>
              .
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              onClick={() => {
                if (retryTarget) {
                  retryScan.mutate(retryTarget.id);
                  setRetryTarget(null);
                }
              }}
              className="bg-indigo-600 hover:bg-indigo-700"
            >
              Retry Scan
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Delete confirm dialog */}
      <AlertDialog
        open={deleteTarget !== null}
        onOpenChange={(open) => {
          if (!open) setDeleteTarget(null);
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Delete this scan?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete the scan and all associated results
              for{" "}
              <span className="font-mono text-xs">
                {deleteTarget?.url.replace(/^https?:\/\//, "").slice(0, 60)}
              </span>
              . This action cannot be undone.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction
              className="bg-destructive hover:bg-destructive/90"
              onClick={() => {
                if (deleteTarget) {
                  deleteScan.mutate(deleteTarget.id);
                  setDeleteTarget(null);
                }
              }}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

