import { useState } from "react";
import { ScrollText, Clock, ChevronLeft, ChevronRight, Filter } from "lucide-react";
import { PageHeader } from "@/components/shared/PageHeader";
import { EmptyState } from "@/components/shared/EmptyState";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Card, CardContent } from "@/components/ui/card";
import { useAuditLog } from "@/hooks/admin/use-audit-log";
import { formatDistanceToNow, format } from "date-fns";

const PAGE_SIZE = 25;

const ACTION_OPTIONS = [
  { value: "all", label: "All actions" },
  { value: "change_plan", label: "Change Plan" },
  { value: "change_role", label: "Change Role" },
  { value: "reset_scan_count", label: "Reset Scan Count" },
  { value: "ban_user", label: "Ban User" },
  { value: "unban_user", label: "Unban User" },
];

const ACTION_LABELS: Record<string, string> = {
  change_plan: "Changed plan",
  change_role: "Changed role",
  reset_scan_count: "Reset scan count",
  ban_user: "Banned user",
  unban_user: "Unbanned user",
};

const ACTION_BADGE_CLASSES: Record<string, string> = {
  change_plan: "bg-blue-100 text-blue-700 border-0",
  change_role: "bg-purple-100 text-purple-700 border-0",
  reset_scan_count: "bg-amber-100 text-amber-700 border-0",
  ban_user: "bg-red-100 text-red-700 border-0",
  unban_user: "bg-green-100 text-green-700 border-0",
};

function MetadataPill({ label, value }: { label: string; value: string }) {
  return (
    <span className="inline-flex items-center gap-1 rounded bg-muted/50 px-1.5 py-0.5 text-2xs font-medium text-foreground/80">
      <span className="text-muted-foreground">{label}:</span>
      <span className="capitalize">{String(value).replace("_", " ")}</span>
    </span>
  );
}

function LogSkeleton() {
  return (
    <div className="space-y-3">
      {Array.from({ length: 8 }).map((_, i) => (
        <div
          key={i}
          className="flex items-start gap-4 rounded-xl border border-border/50 bg-white p-4"
        >
          <Skeleton className="h-8 w-8 rounded-full shrink-0" />
          <div className="flex-1 space-y-2">
            <Skeleton className="h-4 w-64" />
            <Skeleton className="h-3 w-40" />
          </div>
          <Skeleton className="h-4 w-24" />
        </div>
      ))}
    </div>
  );
}

export default function AuditLog() {
  const [page, setPage] = useState(0);
  const [actionFilter, setActionFilter] = useState("");

  const { data, isLoading, isError } = useAuditLog({
    page,
    pageSize: PAGE_SIZE,
    actionFilter: actionFilter || undefined,
  });

  const totalPages = data ? Math.ceil(data.total / PAGE_SIZE) : 0;

  return (
    <div className="space-y-6">
      <PageHeader
        title="Audit Log"
        description="Chronological record of all admin actions."
      />

      {/* Filter */}
      <div className="flex items-center gap-3">
        <Filter className="h-4 w-4 text-muted-foreground" />
        <Select
          value={actionFilter}
          onValueChange={(v) => {
            setActionFilter(v);
            setPage(0);
          }}
        >
          <SelectTrigger className="w-[180px]" aria-label="Filter by action type">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            {ACTION_OPTIONS.map((opt) => (
              <SelectItem key={opt.value} value={opt.value}>
                {opt.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
        {actionFilter && (
          <Button
            variant="ghost"
            size="sm"
            onClick={() => {
              setActionFilter("");
              setPage(0);
            }}
