            Clear filter
          </Button>
        )}
        {data && (
          <span className="ml-auto text-sm text-muted-foreground">
            {data.total.toLocaleString()} entries
          </span>
        )}
      </div>

      {/* Entries */}
      {isLoading ? (
        <LogSkeleton />
      ) : isError ? (
        <div
          role="alert"
          className="flex items-center gap-3 rounded-xl border border-destructive/20 bg-destructive/5 p-4"
        >
          <Filter className="h-5 w-5 text-destructive shrink-0" />
          <p className="text-sm font-medium text-destructive">
            Failed to load audit log. Check your admin permissions or refresh the page.
          </p>
        </div>
      ) : data?.entries.length === 0 ? (
        <EmptyState
          icon={ScrollText}
          title="No audit log entries"
          description={
            actionFilter
              ? "No entries match the selected action filter."
              : "Admin actions will appear here once they occur."
          }
        />
      ) : (
        <ol className="space-y-2.5" aria-label="Audit log entries">
          {data?.entries.map((entry) => {
            const metadata = entry.metadata as Record<string, string>;
            const metaKeys = Object.keys(metadata).filter(
              (k) => metadata[k] !== undefined && metadata[k] !== null
            );

            return (
              <li key={entry.id}>
                <Card className="border-border/50 shadow-soft hover:border-slate-300 transition-colors">
                  <CardContent className="flex items-start gap-4 p-4">
                    {/* Icon */}
                    <div className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-muted/50">
                      <ScrollText className="h-4 w-4 text-slate-500" />
                    </div>

                    {/* Content */}
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span className="text-sm font-medium text-foreground">
                          {entry.admin_name ?? entry.admin_email ?? entry.admin_id}
                        </span>
                        <Badge
                          className={`text-2xs px-1.5 py-0 ${
                            ACTION_BADGE_CLASSES[entry.action] ??
                            "bg-muted/50 text-foreground/80 border-0"
                          }`}
                        >
                          {ACTION_LABELS[entry.action] ?? entry.action}
                        </Badge>
                      </div>

                      {/* Target */}
                      {entry.target_id && (
                        <p className="mt-0.5 font-mono text-xs text-muted-foreground/70">
                          Target: {entry.target_type} · {entry.target_id}
                        </p>
                      )}

                      {/* Metadata pills */}
                      {metaKeys.length > 0 && (
                        <div className="mt-1.5 flex flex-wrap gap-1">
                          {metaKeys.map((k) => (
                            <MetadataPill
                              key={k}
                              label={k.replace(/_/g, " ")}
                              value={String(metadata[k])}
                            />
                          ))}
                        </div>
                      )}
                    </div>

                    {/* Timestamp */}
                    <div className="shrink-0 text-right">
                      <div className="flex items-center gap-1 text-xs text-muted-foreground justify-end">
                        <Clock className="h-3 w-3" />
                        <span title={format(new Date(entry.created_at), "PPpp")}>
                          {formatDistanceToNow(new Date(entry.created_at), {
                            addSuffix: true,
                          })}
                        </span>
                      </div>
                      <p className="mt-0.5 text-2xs text-muted-foreground/50">
                        {format(new Date(entry.created_at), "MMM d, yyyy")}
                      </p>
                    </div>
                  </CardContent>
                </Card>
              </li>
            );
          })}
        </ol>
      )}

      {/* Pagination */}
      {totalPages > 1 && (
        <div className="flex items-center justify-between pt-2">
          <p className="text-sm text-muted-foreground">
            Page {page + 1} of {totalPages}
          </p>
          <div className="flex items-center gap-2">
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.max(0, p - 1))}
              disabled={page === 0}
              aria-label="Previous page"
            >
              <ChevronLeft className="h-4 w-4" />
            </Button>
            <Button
              variant="outline"
              size="sm"
              onClick={() => setPage((p) => Math.min(totalPages - 1, p + 1))}
              disabled={page >= totalPages - 1}
              aria-label="Next page"
            >
              <ChevronRight className="h-4 w-4" />
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

