import { useState, useMemo } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  Search,
  ScanLine,
  MoreVertical,
  Eye,
  RefreshCw,
  Trash2,
  Globe,
} from "lucide-react";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { PageHeader } from "@/components/shared/PageHeader";
import { ScoreRing } from "@/components/shared/ScoreRing";
import { EmptyState } from "@/components/shared/EmptyState";
import { PageTransition } from "@/components/shared/PageTransition";
import { getScoreLabel, getScoreColor } from "@/lib/score-utils";
import { useScans, useDeleteScan } from "@/hooks/use-scans";
import { toast } from "sonner";
import { cn } from "@/lib/utils";

function formatDate(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

// ── Loading skeleton ────────────────────────────────────────────

function ReportCardSkeleton() {
  return (
    <Card className="h-full border-border/50 shadow-soft">
      <CardContent className="p-5 space-y-4">
        <div className="flex items-center gap-2">
          <Skeleton className="h-8 w-8 rounded-lg" />
          <Skeleton className="h-4 w-32" />
        </div>
        <div className="flex justify-center">
          <Skeleton className="h-20 w-20 rounded-full" />
        </div>
        <div className="flex justify-between">
          <Skeleton className="h-3 w-24" />
          <Skeleton className="h-3 w-16" />
        </div>
        <div className="flex justify-between border-t border-border/40 pt-3">
          <Skeleton className="h-3 w-28" />
          <Skeleton className="h-5 w-20 rounded-full" />
        </div>
      </CardContent>
    </Card>
  );
}

// ── Component ───────────────────────────────────────────────────

const Reports = () => {
  const navigate = useNavigate();
  const [search, setSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const [scoreFilter, setScoreFilter] = useState("all");
  const [sortBy, setSortBy] = useState("newest");

  const { data: scans = [], isLoading } = useScans();
  const deleteScan = useDeleteScan();

  const filtered = useMemo(() => {
    let list = [...scans];

    // Search — matches URL, hostname, and page title
    if (search) {
      const q = search.toLowerCase();
      list = list.filter(
        (s) =>
          s.url.toLowerCase().includes(q) ||
          (s.page_title?.toLowerCase().includes(q) ?? false)
      );
    }

    // Status filter
    if (statusFilter !== "all") {
      list = list.filter((s) => s.status === statusFilter);
    }

    // Score filter
    if (scoreFilter !== "all") {
      list = list.filter((s) => {
        if (s.overall_score === null) return false;
        if (scoreFilter === "poor") return s.overall_score < 40;
        if (scoreFilter === "average") return s.overall_score >= 40 && s.overall_score < 70;
        if (scoreFilter === "good") return s.overall_score >= 70;
        return true;
      });
    }

    // Sort
    list.sort((a, b) => {
      if (sortBy === "newest") return new Date(b.created_at).getTime() - new Date(a.created_at).getTime();
      if (sortBy === "oldest") return new Date(a.created_at).getTime() - new Date(b.created_at).getTime();
      if (sortBy === "score-high") return (b.overall_score ?? 0) - (a.overall_score ?? 0);
      if (sortBy === "score-low") return (a.overall_score ?? 0) - (b.overall_score ?? 0);
      return 0;
    });

    return list;
  }, [scans, search, statusFilter, scoreFilter, sortBy]);

  const handleDelete = (scanId: string, hostname: string) => {
    if (!window.confirm(`Delete the scan for ${hostname}? This cannot be undone.`)) return;
    deleteScan.mutate(scanId, {
      onSuccess: () => toast.success("Scan deleted"),
      onError: () => toast.error("Failed to delete scan"),
    });
  };

  return (
    <PageTransition>
      <div className="space-y-6">
        <PageHeader title="My Reports" description="View and manage your CRO audit reports">
          <Button asChild>
            <Link to="/scan">
              <ScanLine className="mr-2 h-4 w-4" />
              New Scan
            </Link>
          </Button>
        </PageHeader>

        {/* Filters */}
        <div className="flex flex-wrap gap-3">
          <div className="relative flex-1 min-w-[200px]">
            <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
            <Input
              placeholder="Search by URL..."
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-9 border-border/50"
            />
          </div>
          <Select value={statusFilter} onValueChange={setStatusFilter}>
            <SelectTrigger className="w-36 border-border/50">
              <SelectValue placeholder="Status" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Status</SelectItem>
              <SelectItem value="completed">Completed</SelectItem>
              <SelectItem value="analyzing">Analyzing</SelectItem>
              <SelectItem value="failed">Failed</SelectItem>
            </SelectContent>
          </Select>
          <Select value={scoreFilter} onValueChange={setScoreFilter}>
            <SelectTrigger className="w-36 border-border/50">
              <SelectValue placeholder="Score" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All Scores</SelectItem>
              <SelectItem value="poor">Poor (0-40)</SelectItem>
              <SelectItem value="average">Average (40-70)</SelectItem>
              <SelectItem value="good">Good (70+)</SelectItem>
            </SelectContent>
          </Select>
          <Select value={sortBy} onValueChange={setSortBy}>
            <SelectTrigger className="w-36 border-border/50">
              <SelectValue placeholder="Sort" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="newest">Newest First</SelectItem>
              <SelectItem value="oldest">Oldest First</SelectItem>
              <SelectItem value="score-high">Score: High-Low</SelectItem>
              <SelectItem value="score-low">Score: Low-High</SelectItem>
            </SelectContent>
          </Select>
        </div>

        {/* Report Cards Grid */}
        {isLoading ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {[1, 2, 3, 4, 5, 6].map((i) => <ReportCardSkeleton key={i} />)}
          </div>
        ) : filtered.length > 0 ? (
          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {filtered.map((scan) => {
              let hostname = scan.url;
              try { hostname = new URL(scan.url).hostname; } catch { /* keep raw */ }
              const displayHostname = hostname.replace("www.", "");
              const faviconUrl = `https://www.google.com/s2/favicons?domain=${hostname}&sz=32`;

              return (
                <Link key={scan.id} to={`/reports/${scan.id}`}>
                  <Card className="group h-full border-border/50 shadow-soft hover:shadow-soft-md transition-all cursor-pointer">
                    <CardContent className="p-5">
                      {/* URL + menu */}
                      <div className="flex items-start justify-between">
                        <div className="flex items-center gap-2 min-w-0">
                          <div className="flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-muted/50 overflow-hidden">
                            <img
                              src={faviconUrl}
                              alt=""
                              className="h-4 w-4"
                              onError={(e) => {
                                const target = e.currentTarget;
                                target.style.display = "none";
                                const parent = target.parentElement;
                                if (parent) {
                                  const fallback = document.createElement("span");
                                  fallback.innerHTML = `<svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="text-muted-foreground"><circle cx="12" cy="12" r="10"/><line x1="2" y1="12" x2="22" y2="12"/><path d="M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z"/></svg>`;
                                  parent.appendChild(fallback);
                                }
                              }}
                            />
                          </div>
                          <span className="truncate text-sm font-medium text-foreground">
                            {displayHostname}
                          </span>
                        </div>
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild onClick={(e) => e.preventDefault()}>
                            <Button variant="ghost" size="sm" className="h-8 w-8 p-0">
                              <MoreVertical className="h-4 w-4 text-muted-foreground" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            <DropdownMenuItem onClick={() => navigate(`/reports/${scan.id}`)}>
                              <Eye className="mr-2 h-3.5 w-3.5" /> View Report
                            </DropdownMenuItem>
                            <DropdownMenuItem onClick={() => navigate(`/scan?url=${encodeURIComponent(scan.url)}&type=${scan.page_type}`)}>
                              <RefreshCw className="mr-2 h-3.5 w-3.5" /> Re-scan
                            </DropdownMenuItem>
                            <DropdownMenuItem
                              className="text-red-600"
                              onClick={(e) => {
                                e.preventDefault();
                                handleDelete(scan.id, hostname);
                              }}
                            >
                              <Trash2 className="mr-2 h-3.5 w-3.5" /> Delete
                            </DropdownMenuItem>
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>

                      {/* Score */}
                      <div className="my-4 flex flex-col items-center gap-1">
                        {scan.overall_score !== null ? (
                          <>
                            <ScoreRing score={scan.overall_score} size={80} strokeWidth={5} showLabel={false} />
                            <span className={cn("text-sm font-semibold tabular-nums", getScoreColor(scan.overall_score))}>
                              {getScoreLabel(scan.overall_score)}
                            </span>
                          </>
                        ) : (
                          <div className="flex h-20 w-20 items-center justify-center rounded-full border-4 border-border/40">
                            <span className="text-xs text-muted-foreground">N/A</span>
                          </div>
                        )}
                      </div>

                      {/* Stats */}
                      <div className="flex items-center justify-between text-xs text-muted-foreground">
                        <span>
                          {scan.issues_found} issues
                          {scan.critical_issues > 0 && (
                            <span className="ml-1 font-medium text-red-500">&middot; {scan.critical_issues} critical</span>
                          )}
                        </span>
                        <Badge variant="outline" className="text-2xs capitalize">
                          {scan.page_type}
                        </Badge>
                      </div>

                      {/* Date + Status */}
                      <div className="mt-3 flex items-center justify-between border-t border-border/40 pt-3">
                        <span className="text-xs text-muted-foreground">
                          {formatDate(scan.created_at)}
                        </span>
                        {scan.status === "completed" ? (
                          <Badge variant="outline" className="border-emerald-200/80 bg-emerald-50/50 text-emerald-700 text-2xs">
                            Completed
                          </Badge>
                        ) : scan.status === "analyzing" ? (
                          <Badge variant="outline" className="border-amber-200/80 bg-amber-50/50 text-amber-700 text-2xs animate-pulse">
                            Analyzing
                          </Badge>
                        ) : (
                          <Badge variant="outline" className="text-2xs capitalize">{scan.status}</Badge>
                        )}
                      </div>
                    </CardContent>
                  </Card>
                </Link>
              );
            })}
          </div>
        ) : (
          <EmptyState
            icon={ScanLine}
            title="No reports found"
            description={
              search || statusFilter !== "all" || scoreFilter !== "all"
                ? "Try adjusting your filters to find what you're looking for."
                : "Run your first CRO audit to see results here."
            }
            actionLabel="Start New Scan"
            actionHref="/scan"
          />
        )}
      </div>
    </PageTransition>
  );
};

export default Reports;

