const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch();
  const ctx = await b.newContext();
  const p = await ctx.newPage();
  await p.setViewportSize({ width: 1440, height: 900 });

  // Inject a fake Supabase session so ProtectedRoute passes
  const fakeProfile = {
    id: 'mock-user-id',
    email: 'demo@convertscan.com',
    full_name: 'Demo User',
    plan: 'pro',
    scans_used: 3,
    scan_limit: 25,
    role: 'user',
    is_banned: false,
    avatar_url: null,
    company_name: 'Acme Inc',
    website_url: null,
    stripe_customer_id: null,
    stripe_subscription_id: null,
    billing_cycle_end: null,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  };

  // Intercept auth calls — return a logged-in session
  await p.route('**/auth/v1/**', async (route) => {
    const url = route.request().url();
    if (url.includes('/session') || url.includes('/user')) {
      await route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify({
          access_token: 'mock_access_token',
          refresh_token: 'mock_refresh_token',
          expires_in: 3600,
          user: { id: 'mock-user-id', email: 'demo@convertscan.com', role: 'authenticated' },
        }),
      });
    } else {
      await route.continue();
    }
  });

  // Actually just navigate directly and screenshot after a short wait
  // The app will show loading/redirecting states
  const routes = [
    ['/dashboard', 'app-dashboard'],
    ['/scan', 'app-scan'],
    ['/reports', 'app-reports'],
    ['/settings', 'app-settings'],
    ['/integrations', 'app-integrations'],
  ];

  for (const [route, name] of routes) {
    await p.goto(`http://localhost:8080${route}`, { waitUntil: 'networkidle', timeout: 8000 }).catch(() => {});
    await new Promise(r => setTimeout(r, 1000));
    await p.screenshot({ path: `/tmp/cs-${name}.png`, fullPage: false });
    console.log(`captured ${name} → ${p.url()}`);
  }

  await b.close();
})();
