                <Route path="/agents" element={<AgentHub />} />
                <Route path="/agents/:taskId" element={<AgentWorkspace />} />
                <Route path="/integrations" element={<Integrations />} />
                <Route path="/settings" element={<SettingsPage />} />
              </Route>

              {/* Admin routes — nested inside ProtectedRoute, guarded by AdminRoute */}
              <Route element={<AdminRoute />}>
                <Route
                  path="/admin"
                  element={
                    <Suspense fallback={<AdminLoadingSpinner />}>
                      <AdminLayout />
                    </Suspense>
                  }
                >
                  <Route
                    index
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminDashboard />
                      </Suspense>
                    }
                  />
                  <Route
                    path="users"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminUsers />
                      </Suspense>
                    }
                  />
                  <Route
                    path="users/:userId"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminUserDetail />
                      </Suspense>
                    }
                  />
                  <Route
                    path="audit-log"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminAuditLog />
                      </Suspense>
                    }
                  />
                  <Route
                    path="scans"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminScans />
                      </Suspense>
                    }
                  />
                  <Route
                    path="billing"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminBilling />
                      </Suspense>
                    }
                  />
                  <Route
                    path="system"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminSystem />
                      </Suspense>
                    }
                  />
                  <Route
                    path="flags"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminFeatureFlags />
                      </Suspense>
                    }
                  />
                  <Route
                    path="support"
                    element={
                      <Suspense fallback={<AdminLoadingSpinner />}>
                        <AdminSupport />
                      </Suspense>
                    }
                  />
                </Route>
              </Route>
            </Route>

            <Route path="*" element={<NotFound />} />
          </Routes>
        </AuthProvider>
      </BrowserRouter>
      </TooltipProvider>
    </QueryClientProvider>
  </ThemeProvider>
);

export default App;

