import { useState } from "react";
import { Outlet, Link, useLocation, useNavigate } from "react-router-dom";
import {
  LayoutDashboard,
  Users,
  ScanLine,
  CreditCard,
  Activity,
  ToggleLeft,
  MessageSquare,
  ScrollText,
  ArrowLeft,
  ChevronLeft,
  ChevronRight,
  LogOut,
  Settings,
  User,
} from "lucide-react";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { useAuth } from "@/contexts/AuthContext";
import { cn } from "@/lib/utils";

interface AdminNavItem {
  title: string;
  href: string;
  icon: React.ElementType;
  disabled?: boolean;
  badge?: string;
}

const NAV_ITEMS: AdminNavItem[] = [
  { title: "Dashboard", href: "/admin", icon: LayoutDashboard },
  { title: "Users", href: "/admin/users", icon: Users },
  { title: "Scans", href: "/admin/scans", icon: ScanLine },
  { title: "Billing", href: "/admin/billing", icon: CreditCard },
  { title: "System", href: "/admin/system", icon: Activity },
  { title: "Feature Flags", href: "/admin/flags", icon: ToggleLeft },
  { title: "Support", href: "/admin/support", icon: MessageSquare },
  { title: "Audit Log", href: "/admin/audit-log", icon: ScrollText },
];

export function AdminLayout() {
  const [collapsed, setCollapsed] = useState<boolean>(() => {
    try { return sessionStorage.getItem("admin:sidebar") === "true"; } catch { return false; }
  });
  const location = useLocation();
  const navigate = useNavigate();
  const { profile, signOut } = useAuth();

  const displayName = profile?.full_name ?? "Admin";
  const initials = displayName
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);

  const isActive = (href: string) => {
    if (href === "/admin") return location.pathname === "/admin";
    return location.pathname.startsWith(href);
  };

  const handleLogout = async () => {
    await signOut();
    navigate("/login", { replace: true });
  };

  return (
    <div className="min-h-screen flex w-full">
      {/* Sidebar */}
      <aside
        className={cn(
          "flex flex-col shrink-0 bg-sidebar transition-all duration-200",
          collapsed ? "w-[60px]" : "w-[240px]"
        )}
      >
        {/* Header */}
        <div className="flex h-14 items-center justify-between px-3 border-b border-white/5">
          {!collapsed && (
            <div className="flex items-center gap-2.5">
              <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary shrink-0">
                <ScanLine className="h-3.5 w-3.5 text-white" />
              </div>
              <div className="flex flex-col leading-tight">
                <span className="text-sm font-semibold text-white tracking-tight">
                  ConvertScan
                </span>
                <span className="text-2xs text-white/30 font-medium uppercase tracking-wider">
                  Admin
                </span>
              </div>
            </div>
          )}
          {collapsed && (
            <div className="flex h-7 w-7 items-center justify-center rounded-md bg-primary mx-auto">
              <ScanLine className="h-3.5 w-3.5 text-white" />
            </div>
          )}
        </div>

        {/* Nav */}
        <nav className="flex-1 px-2 py-3 space-y-0.5 overflow-y-auto">
          {NAV_ITEMS.map((item) => {
            const active = isActive(item.href);
            return (
              <div key={item.href}>
                {item.disabled ? (
                  <div
                    className={cn(
                      "flex items-center gap-2.5 rounded-md px-2.5 py-2 cursor-not-allowed opacity-30",
                      collapsed ? "justify-center" : ""
                    )}
                    title={item.disabled ? `Coming soon` : item.title}
                  >
                    <item.icon className="h-4 w-4 text-white/60 shrink-0" />
                    {!collapsed && (
                      <span className="text-sm text-white/60 flex-1 truncate">
                        {item.title}
                      </span>
                    )}
                    {!collapsed && item.badge && (
                      <Badge
                        variant="outline"
                        className="border-white/10 text-white/25 text-2xs px-1 py-0 leading-tight"
                      >
                        {item.badge}
                      </Badge>
                    )}
                  </div>
                ) : (
                  <Link
                    to={item.href}
                    className={cn(
                      "flex items-center gap-2.5 rounded-md px-2.5 py-2 transition-colors duration-150",
                      collapsed ? "justify-center" : "",
                      active
                        ? "bg-white/10 text-white"
                        : "text-white/50 hover:bg-white/5 hover:text-white/80"
                    )}
                    title={collapsed ? item.title : undefined}
                  >
                    <item.icon
                      className={cn(
                        "h-4 w-4 shrink-0",
                        active ? "text-primary" : ""
                      )}
                    />
                    {!collapsed && (
                      <span
                        className={cn(
                          "text-sm truncate",
                          active ? "font-medium" : ""
                        )}
                      >
                        {item.title}
                      </span>
                    )}
                  </Link>
                )}
              </div>
            );
          })}

          <Separator className="my-2 bg-white/[0.06]" />

          <Link
            to="/dashboard"
            className={cn(
              "flex items-center gap-2.5 rounded-md px-2.5 py-2 text-white/40 hover:text-white/70 hover:bg-white/5 transition-colors",
              collapsed ? "justify-center" : ""
            )}
            title={collapsed ? "Back to App" : undefined}
          >
            <ArrowLeft className="h-4 w-4 shrink-0" />
            {!collapsed && (
              <span className="text-sm">Back to App</span>
            )}
          </Link>
        </nav>

        {/* Footer */}
        <div className="border-t border-white/5 p-2 space-y-2">
          {!collapsed && (
            <div className="flex items-center gap-2 px-1.5 py-1 rounded-md">
              <Avatar className="h-6 w-6 shrink-0">
                {profile?.avatar_url && (
                  <AvatarImage src={profile.avatar_url} alt={displayName} />
                )}
                <AvatarFallback className="bg-primary/20 text-2xs font-medium text-primary">
                  {initials}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <p className="text-xs font-medium text-white truncate">
                  {displayName.split(" ")[0]}
                </p>
                <p className="text-2xs text-white/30 capitalize">
                  {profile?.role?.replace("_", " ") ?? "admin"}
                </p>
              </div>
            </div>
          )}
          <button
            onClick={() => setCollapsed((c) => {
            const next = !c;
            try { sessionStorage.setItem("admin:sidebar", String(next)); } catch {}
            return next;
          })}
            className="flex w-full items-center justify-center rounded-md p-1.5 text-white/25 hover:bg-white/5 hover:text-white/50 transition-colors"
            aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            {collapsed ? (
              <ChevronRight className="h-4 w-4" />
            ) : (
              <ChevronLeft className="h-4 w-4" />
            )}
          </button>
        </div>
      </aside>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Admin top bar */}
        <header className="flex h-14 items-center justify-between border-b border-border/50 bg-white/80 backdrop-blur-sm px-6 shrink-0">
          <div className="flex items-center gap-3">
            <Badge
              className="bg-primary/8 text-primary border-primary/15 text-xs font-medium px-2 py-0.5"
            >
              Admin
            </Badge>
            <span className="text-border text-sm">/</span>
            <span className="text-sm text-muted-foreground">
              {location.pathname === "/admin"
                ? "Dashboard"
                : location.pathname
                    .split("/")
                    .filter(Boolean)
                    .slice(1)
                    .map((s) =>
                      s
                        .split("-")
                        .map((w) => w[0].toUpperCase() + w.slice(1))
                        .join(" ")
                    )
                    .join(" / ")}
            </span>
          </div>

          <div className="flex items-center gap-2">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button className="flex items-center gap-2 rounded-lg px-2 py-1 hover:bg-muted/50 transition-colors">
                  <Avatar className="h-6 w-6">
                    {profile?.avatar_url && (
                      <AvatarImage src={profile.avatar_url} alt={displayName} />
                    )}
                    <AvatarFallback className="bg-primary/8 text-2xs font-medium text-primary">
                      {initials}
                    </AvatarFallback>
                  </Avatar>
                  <div className="hidden sm:flex flex-col items-start leading-tight">
                    <span className="text-xs font-medium text-foreground">
                      {displayName.split(" ")[0]}
                    </span>
                    <span className="text-2xs text-muted-foreground capitalize">
                      {profile?.role?.replace("_", " ") ?? "admin"}
                    </span>
                  </div>
                </button>
              </DropdownMenuTrigger>
              <DropdownMenuContent align="end" className="w-48">
                <div className="px-2 py-1.5">
                  <p className="text-sm font-medium text-foreground">{displayName}</p>
                  <p className="text-xs text-muted-foreground">{profile?.email ?? ""}</p>
                </div>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => navigate("/settings")}>
                  <User className="mr-2 h-3.5 w-3.5" />
                  Profile
                </DropdownMenuItem>
                <DropdownMenuItem onClick={() => navigate("/settings")}>
                  <Settings className="mr-2 h-3.5 w-3.5" />
                  Settings
                </DropdownMenuItem>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={handleLogout} className="text-destructive">
                  <LogOut className="mr-2 h-3.5 w-3.5" />
                  Log out
                </DropdownMenuItem>
              </DropdownMenuContent>
            </DropdownMenu>
          </div>
        </header>

        {/* Page content */}
        <main className="flex-1 p-4 md:p-6 lg:p-8 bg-background overflow-auto">
          <div className="mx-auto max-w-[1140px]">
            <Outlet />
          </div>
        </main>
      </div>
    </div>
  );
}

