import { useLocation, useNavigate, Link } from "react-router-dom";
import { SidebarTrigger } from "@/components/ui/sidebar";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Bell, LogOut, Settings, User, ChevronRight, ShieldCheck } from "lucide-react";
import { useAuth } from "@/contexts/AuthContext";

const pageTitles: Record<string, string> = {
  "/dashboard": "Dashboard",
  "/scan": "New Scan",
  "/reports": "My Reports",
  "/integrations": "Integrations",
  "/settings": "Settings",
  "/pricing": "Pricing",
  "/admin": "Admin Dashboard",
  "/admin/users": "Users",
  "/admin/scans": "Scans",
  "/admin/billing": "Billing",
  "/admin/system": "System",
  "/admin/flags": "Feature Flags",
  "/admin/support": "Support",
  "/admin/audit-log": "Audit Log",
};

export function TopBar() {
  const location = useLocation();
  const navigate = useNavigate();
  const { profile, signOut } = useAuth();

  const displayName = profile?.full_name ?? "User";
  const initials = displayName
    .split(" ")
    .map((n) => n[0])
    .join("")
    .toUpperCase()
    .slice(0, 2);

  const pathSegments = location.pathname.split("/").filter(Boolean);
  const title = pageTitles[location.pathname] ?? pageTitles[`/${pathSegments[0]}`] ?? "ConvertScan";
  const isDetailPage = pathSegments.length > 1;

  const handleLogout = async () => {
    await signOut();
    navigate("/login", { replace: true });
  };

  return (
    <header className="flex h-14 items-center justify-between border-b border-border/50 bg-background/80 backdrop-blur-sm px-4 shrink-0">
      <div className="flex items-center gap-3">
        <SidebarTrigger className="text-muted-foreground hover:text-foreground transition-colors" />

        <div className="flex items-center gap-1.5 text-sm">
          {isDetailPage ? (
            <>
              <Link
                to={`/${pathSegments[0]}`}
                className="text-muted-foreground hover:text-foreground transition-colors"
              >
                {pageTitles[`/${pathSegments[0]}`] ?? pathSegments[0]}
              </Link>
              <ChevronRight className="h-3 w-3 text-muted-foreground/50" />
              <span className="font-medium text-foreground truncate max-w-[160px] sm:max-w-xs">
                Report
              </span>
            </>
          ) : (
            <span className="font-medium text-foreground">{title}</span>
          )}
        </div>
      </div>

      <div className="flex items-center gap-1">
        {/* Notification bell */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button variant="ghost" size="sm" className="relative h-8 w-8 p-0 text-muted-foreground hover:text-foreground">
              <Bell className="h-4 w-4" />
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-72">
            <div className="px-3 py-2">
              <p className="text-sm font-medium text-foreground">Notifications</p>
            </div>
            <DropdownMenuSeparator />
            <div className="px-3 py-6 text-center">
              <p className="text-sm text-muted-foreground">No new notifications</p>
            </div>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => navigate("/settings")} className="justify-center text-xs text-primary">
              Notification settings
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>

        {/* User dropdown */}
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button className="flex items-center gap-2 rounded-lg px-2 py-1 hover:bg-muted/50 transition-colors">
              <Avatar className="h-6 w-6">
                {profile?.avatar_url && (
                  <AvatarImage src={profile.avatar_url} alt={displayName} />
                )}
                <AvatarFallback className="bg-primary/8 text-2xs font-medium text-primary">
                  {initials}
                </AvatarFallback>
              </Avatar>
              <span className="hidden text-sm font-medium text-foreground sm:inline">
                {displayName.split(" ")[0]}
              </span>
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align="end" className="w-48">
            <div className="px-2 py-1.5">
              <p className="text-sm font-medium text-foreground">{displayName}</p>
              <p className="text-xs text-muted-foreground">{profile?.email ?? ""}</p>
            </div>
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={() => navigate("/settings")}>
              <User className="mr-2 h-3.5 w-3.5" />
              Profile
            </DropdownMenuItem>
            <DropdownMenuItem onClick={() => navigate("/settings")}>
              <Settings className="mr-2 h-3.5 w-3.5" />
              Settings
            </DropdownMenuItem>
            {(profile?.role === "admin" || profile?.role === "super_admin") && (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onClick={() => navigate("/admin")}>
                  <ShieldCheck className="mr-2 h-3.5 w-3.5" />
                  Admin Panel
                </DropdownMenuItem>
              </>
            )}
            <DropdownMenuSeparator />
            <DropdownMenuItem onClick={handleLogout} className="text-destructive">
              <LogOut className="mr-2 h-3.5 w-3.5" />
              Log out
            </DropdownMenuItem>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    </header>
  );
}

