// ── Plan Limits Editor ────────────────────────────────────────

function PlanLimitsEditor({ isSuperAdmin }: { isSuperAdmin: boolean }) {
  const planLimitsQuery = usePlanLimits();
  const updatePlanLimits = useUpdatePlanLimits();

  const [localLimits, setLocalLimits] = useState<PlanLimits>({
    free: 3,
    pro: 25,
    agency: 500,
  });

  // Seed local state from DB
  useEffect(() => {
    if (planLimitsQuery.data) {
      setLocalLimits(planLimitsQuery.data);
    }
  }, [planLimitsQuery.data]);

  const handleSave = () => {
    updatePlanLimits.mutate(localLimits);
  };

  const plans: { key: keyof PlanLimits; label: string; badge: string }[] = [
    { key: "free", label: "Free", badge: "bg-muted/50 text-foreground/80 border-0" },
    { key: "pro", label: "Pro", badge: "bg-indigo-100 text-indigo-700 border-0" },
    { key: "agency", label: "Agency", badge: "bg-purple-100 text-purple-700 border-0" },
  ];

  if (planLimitsQuery.isLoading) {
    return (
      <div className="space-y-2">
        {Array.from({ length: 3 }).map((_, i) => (
          <Skeleton key={i} className="h-10 w-full rounded-lg" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {plans.map(({ key, label, badge }) => (
        <div
          key={key}
          className="flex items-center justify-between rounded-lg bg-muted/40 px-4 py-2.5 gap-3"
        >
          <Badge className={`text-xs px-2 py-0.5 shrink-0 ${badge}`}>
            {label}
          </Badge>
          {isSuperAdmin ? (
            <div className="flex items-center gap-2 ml-auto">
              <Input
                type="number"
                value={localLimits[key]}
                onChange={(e) => {
                  const val = parseInt(e.target.value, 10);
                  if (!isNaN(val) && val >= 1 && val <= 10000) {
                    setLocalLimits((prev) => ({ ...prev, [key]: val }));
                  }
                }}
                min={1}
                max={10000}
                className="w-24 h-7 text-sm text-right tabular-nums"
                aria-label={`${label} scan limit`}
              />
              <span className="text-xs text-muted-foreground whitespace-nowrap">
                scans / mo
              </span>
            </div>
          ) : (
            <span className="text-sm font-semibold text-foreground tabular-nums ml-auto">
              {localLimits[key]} scans / month
            </span>
          )}
        </div>
      ))}
      {isSuperAdmin && (
        <Button
          size="sm"
          className="w-full mt-2"
          onClick={handleSave}
          disabled={updatePlanLimits.isPending}
        >
          {updatePlanLimits.isPending ? (
            <>
              <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
              Saving…
            </>
          ) : (
            <>
              <Save className="mr-2 h-3.5 w-3.5" />
              Save Plan Limits
            </>
          )}
        </Button>
      )}
    </div>
  );
}

// ── Pillar Weights Editor ─────────────────────────────────────

function PillarWeightsEditor({ isSuperAdmin }: { isSuperAdmin: boolean }) {
  const pillarWeightsQuery = usePillarWeights();
  const updatePillarWeights = useUpdatePillarWeights();

  // Local state in percentages (0-100)
  const [localWeights, setLocalWeights] = useState<Record<string, number>>({
    value_proposition: 25,
    cta_effectiveness: 20,
    trust_signals: 15,
    visual_hierarchy: 15,
    mobile_experience: 10,
    content_copy: 10,
    page_performance: 5,
  });

  // Seed from DB (stored as decimals, display as percentages)
  useEffect(() => {
    if (pillarWeightsQuery.data) {
      const percentages: Record<string, number> = {};
      for (const [key, val] of Object.entries(pillarWeightsQuery.data)) {
        percentages[key] = Math.round(val * 100);
      }
      setLocalWeights(percentages);
    }
  }, [pillarWeightsQuery.data]);

  const totalPercent = Object.values(localWeights).reduce((s, v) => s + v, 0);
  const totalOk = totalPercent === 100;

  const handleSave = () => {
    // Convert back to decimals
    const decimals: Record<string, number> = {};
    for (const [key, val] of Object.entries(localWeights)) {
      decimals[key] = val / 100;
    }
    updatePillarWeights.mutate(decimals);
  };

  if (pillarWeightsQuery.isLoading) {
    return (
      <div className="space-y-1.5">
        {Array.from({ length: 7 }).map((_, i) => (
          <Skeleton key={i} className="h-7 w-full rounded" />
        ))}
      </div>
    );
  }

  return (
    <div className="space-y-2">
      {PILLAR_DEFINITIONS.map((pillar) => {
        const pct = localWeights[pillar.key] ?? 0;
        return (
          <div key={pillar.key} className="flex items-center justify-between gap-3">
            <span className="text-xs text-muted-foreground flex-1 truncate">
              {pillar.label}
            </span>
            {isSuperAdmin ? (
              <div className="flex items-center gap-1.5">
                <Input
                  type="number"
                  value={pct}
                  onChange={(e) => {
                    const val = parseInt(e.target.value, 10);
                    if (!isNaN(val) && val >= 0 && val <= 100) {
                      setLocalWeights((prev) => ({ ...prev, [pillar.key]: val }));
                    }
                  }}
                  min={0}
                  max={100}
                  className="w-16 h-7 text-xs text-right tabular-nums"
                  aria-label={`${pillar.label} weight %`}
                />
                <span className="text-xs text-muted-foreground">%</span>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <div className="w-24 h-1.5 rounded-full bg-muted/50 overflow-hidden">
                  <div
                    className="h-full rounded-full bg-primary/60"
                    style={{ width: `${pct}%` }}
                  />
                </div>
                <span className="text-xs font-medium text-muted-foreground w-8 text-right tabular-nums">
                  {pct}%
                </span>
              </div>
            )}
          </div>
        );
      })}

      {isSuperAdmin && (
        <>
          {/* Total indicator */}
          <div
            className={cn(
              "flex items-center justify-between rounded-lg px-3 py-2 mt-2 text-xs font-medium",
              totalOk
                ? "bg-green-50 text-green-700"
                : "bg-red-50 text-red-700"
            )}
          >
            <span>Total</span>
            <span className="tabular-nums">{totalPercent}%</span>
          </div>

          <Button
            size="sm"
            className="w-full mt-1"
            onClick={handleSave}
            disabled={!totalOk || updatePillarWeights.isPending}
            title={totalOk ? undefined : "Weights must sum to exactly 100%"}
          >
            {updatePillarWeights.isPending ? (
              <>
                <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
                Saving…
              </>
            ) : (
              <>
                <Save className="mr-2 h-3.5 w-3.5" />
                Save Pillar Weights
              </>
            )}
          </Button>
        </>
      )}
    </div>
  );
}

// ── Main page ─────────────────────────────────────────────────

export default function AdminSystem() {
  const { profile } = useAuth();
  const isSuperAdmin = profile?.role === "super_admin";

  const statsQuery = useSystemStats();
  const resetScans = useResetMonthlyScans();
  const clearFailed = useClearFailedScans();

  const stripeConfigured = Boolean(
    import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY
  );
  const supabaseConfigured = Boolean(
    import.meta.env.VITE_SUPABASE_URL &&
      (import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY ||
        import.meta.env.VITE_SUPABASE_ANON_KEY)
  );

  return (
    <div className="space-y-8">
      <PageHeader
        title="System"
        description="Health status, database stats, and platform configuration."
      />

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* Environment status */}
        <Card className="border-border/50 shadow-soft">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Server className="h-4 w-4 text-muted-foreground" />
              <CardTitle className="text-base font-semibold">
                Environment Status
              </CardTitle>
            </div>
          </CardHeader>
          <CardContent className="divide-y divide-slate-100">
            <StatusIndicator
              connected={
                supabaseConfigured
                  ? statsQuery.data?.supabaseConnected ?? "unknown"
                  : false
              }
              label="Supabase"
              note="Database + Auth"
            />
            <StatusIndicator
              connected={stripeConfigured ? "unknown" : false}
              label="Stripe"
              note={
                stripeConfigured
                  ? "Publishable key set"
                  : "VITE_STRIPE_PUBLISHABLE_KEY not set"
              }
            />
            <StatusIndicator
              connected="unknown"
              label="AI Engine"
              note="API key configured server-side"
            />
            <StatusIndicator
              connected="unknown"
              label="Email Service"
              note="Configured server-side"
            />
          </CardContent>
        </Card>

        {/* Database stats */}
        <Card className="border-border/50 shadow-soft">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Database className="h-4 w-4 text-muted-foreground" />
              <CardTitle className="text-base font-semibold">
                Database Stats
              </CardTitle>
            </div>
          </CardHeader>
          <CardContent className="divide-y divide-slate-100">
            <DbStatRow
              label="Total Users (profiles)"
              value={statsQuery.data?.profilesCount ?? 0}
              isLoading={statsQuery.isLoading}
            />
            <DbStatRow
              label="Total Scans"
              value={statsQuery.data?.scansCount ?? 0}
              isLoading={statsQuery.isLoading}
            />
            <DbStatRow
              label="Total Scan Results"
              value={statsQuery.data?.scanResultsCount ?? 0}
              isLoading={statsQuery.isLoading}
            />
            <DbStatRow
              label="Scans with Screenshots"
              value={statsQuery.data?.screenshotsCount ?? 0}
              isLoading={statsQuery.isLoading}
            />
          </CardContent>
        </Card>
      </div>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2">
        {/* App config — editable */}
        <Card className="border-border/50 shadow-soft">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <Activity className="h-4 w-4 text-muted-foreground" />
              <CardTitle className="text-base font-semibold">
                App Configuration
              </CardTitle>
            </div>
            {isSuperAdmin && (
              <p className="text-xs text-muted-foreground mt-1">
                Editing enabled — you are a super admin.
              </p>
            )}
          </CardHeader>
          <CardContent className="space-y-6">
            {/* Plan limits */}
            <div>
              <Label className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-3 block">
                Scan Limits per Plan
              </Label>
              <PlanLimitsEditor isSuperAdmin={isSuperAdmin} />
            </div>

            {/* Pillar weights */}
            <div>
              <Label className="text-xs font-medium uppercase tracking-wider text-muted-foreground mb-3 block">
                CRO Pillar Weights
              </Label>
              <PillarWeightsEditor isSuperAdmin={isSuperAdmin} />
            </div>
          </CardContent>
        </Card>

        {/* Quick actions — super_admin only */}
        <Card className="border-border/50 shadow-soft">
          <CardHeader className="pb-3">
            <div className="flex items-center gap-2">
              <ShieldAlert className="h-4 w-4 text-muted-foreground" />
              <CardTitle className="text-base font-semibold">
                Quick Actions
              </CardTitle>
            </div>
          </CardHeader>
          <CardContent className="space-y-4">
            {!isSuperAdmin ? (
              <div className="rounded-xl border border-dashed border-border/50 p-6 text-center">
                <ShieldAlert className="mx-auto h-8 w-8 text-muted-foreground/40 mb-2" />
                <p className="text-sm font-medium text-foreground">
                  Super Admin required
                </p>
                <p className="text-xs text-muted-foreground mt-1">
                  These actions are restricted to super administrators only.
                </p>
              </div>
            ) : (
              <>
                {/* Reset monthly scans */}
                <div className="rounded-lg border border-border/50 p-4 space-y-2">
                  <div className="flex items-center gap-2">
                    <RotateCcw className="h-4 w-4 text-amber-500" />
                    <p className="text-sm font-medium">
                      Reset Monthly Scan Counters
                    </p>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Resets the{" "}
                    <code className="font-mono text-xs bg-muted/50 px-1 py-0.5 rounded">
                      scans_used
                    </code>{" "}
                    counter to 0 for all users. Typically run on the 1st of each
                    month.
                  </p>
                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button
                        variant="outline"
                        size="sm"
                        className="w-full mt-1 border-amber-200 hover:bg-amber-50 hover:border-amber-300"
                        disabled={resetScans.isPending}
                      >
                        {resetScans.isPending ? (
                          <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <RotateCcw className="mr-2 h-3.5 w-3.5" />
                        )}
                        {resetScans.isPending ? "Resetting…" : "Reset All Counters"}
                      </Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>
                          Reset all monthly scan counters?
                        </AlertDialogTitle>
                        <AlertDialogDescription>
                          This will call the{" "}
                          <code className="font-mono text-xs bg-muted/50 px-1 py-0.5 rounded">
                            reset_monthly_scans
                          </code>{" "}
                          RPC and set every user's scan count back to 0. This
                          cannot be undone.
                        </AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                          onClick={() => resetScans.mutate()}
                          className="bg-amber-600 hover:bg-amber-700"
                        >
                          Reset All
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>

                {/* Clear failed scans */}
                <div className="rounded-lg border border-border/50 p-4 space-y-2">
                  <div className="flex items-center gap-2">
                    <Trash2 className="h-4 w-4 text-red-500" />
                    <p className="text-sm font-medium">Clear Old Failed Scans</p>
                  </div>
                  <p className="text-xs text-muted-foreground">
                    Permanently deletes scans with{" "}
                    <code className="font-mono text-xs bg-muted/50 px-1 py-0.5 rounded">
                      status = failed
                    </code>{" "}
                    older than 30 days. Frees up storage and cleans up the scan
                    table.
                  </p>
                  <AlertDialog>
                    <AlertDialogTrigger asChild>
                      <Button
                        variant="outline"
                        size="sm"
                        className="w-full mt-1 border-red-200 hover:bg-red-50 hover:border-red-300 text-red-600"
                        disabled={clearFailed.isPending}
                      >
                        {clearFailed.isPending ? (
                          <Loader2 className="mr-2 h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <Trash2 className="mr-2 h-3.5 w-3.5" />
                        )}
                        {clearFailed.isPending ? "Clearing…" : "Clear Failed Scans"}
                      </Button>
                    </AlertDialogTrigger>
                    <AlertDialogContent>
                      <AlertDialogHeader>
                        <AlertDialogTitle>
                          Clear old failed scans?
                        </AlertDialogTitle>
                        <AlertDialogDescription>
                          This will permanently delete all failed scans older
                          than 30 days, including their associated results. This
                          cannot be undone.
                        </AlertDialogDescription>
                      </AlertDialogHeader>
                      <AlertDialogFooter>
                        <AlertDialogCancel>Cancel</AlertDialogCancel>
                        <AlertDialogAction
                          onClick={() => clearFailed.mutate()}
                          className="bg-destructive hover:bg-destructive/90"
                        >
                          Delete Old Scans
                        </AlertDialogAction>
                      </AlertDialogFooter>
                    </AlertDialogContent>
                  </AlertDialog>
                </div>

                {/* Quick wins notice */}
                <div className="rounded-lg border border-dashed border-border/50 px-4 py-3">
                  <div className="flex items-center gap-2">
                    <Zap className="h-3.5 w-3.5 text-muted-foreground/60" />
                    <p className="text-xs text-muted-foreground">
                      More system actions will be added here as the platform
                      grows.
                    </p>
                  </div>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

