import { useAuth } from "@/hooks/useAuth";
import { supabase } from "@/integrations/supabase/client";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import { LogOut, Zap } from "lucide-react";
import { toast } from "sonner";
import ChangePasswordCard from "@/components/settings/ChangePasswordCard";
import { FadeIn } from "@/components/ui/fade-in";
import { StaggerList } from "@/components/ui/stagger-list";

const Settings = () => {
  const { user, profile, signOut, refreshProfile } = useAuth();
  const autoRank = profile?.auto_rank_enabled ?? true;

  const toggleAutoRank = async (enabled: boolean) => {
    if (!user) return;
    try {
      const { error } = await supabase
        .from("profiles")
        .update({ auto_rank_enabled: enabled } as any)
        .eq("user_id", user.id);
      if (error) throw error;
      await refreshProfile();
      toast.success(enabled ? "Auto-rank enabled" : "Auto-rank disabled");
    } catch {
      toast.error("Failed to update setting");
    }
  };

  return (
    <SidebarLayout>
      <main className="w-full max-w-[700px] mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <FadeIn>
          <h1 className="text-xl font-semibold text-foreground tracking-tight mb-6">Settings</h1>
        </FadeIn>
        <StaggerList className="space-y-6" stagger={0.08}>
          {/* Auto-rank toggle */}
          <Card>
            <CardHeader className="pb-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Zap className="h-5 w-5 text-primary" />
                  <CardTitle className="text-lg">Auto-rank resumes</CardTitle>
                </div>
                <Switch checked={autoRank} onCheckedChange={toggleAutoRank} />
              </div>
              <CardDescription>
                {autoRank
                  ? "Resumes are automatically scored after upload. Credits are used immediately."
                  : "Resumes stay as Pending after upload. You choose when to rank and spend credits."}
              </CardDescription>
            </CardHeader>
          </Card>

          <ChangePasswordCard />

          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-lg">
                <LogOut className="h-5 w-5" />
                Account
              </CardTitle>
            </CardHeader>
            <CardContent>
              <Button variant="outline" onClick={signOut}>
                Sign out
              </Button>
            </CardContent>
          </Card>
        </StaggerList>
      </main>
    </SidebarLayout>
  );
};

export default Settings;

