          <button
            onClick={() => {
              setCollapsed((c) => {
                const next = !c;
                try { sessionStorage.setItem("admin:sidebar", String(next)); } catch {}
                return next;
              });
            }}
            className="flex w-full items-center justify-center rounded-md p-1.5 text-white/25 hover:bg-white/5 hover:text-white/50 transition-colors"
            aria-label={collapsed ? "Expand sidebar" : "Collapse sidebar"}
          >
            {collapsed ? (
              <ChevronRight className="h-4 w-4" />
            ) : (
              <ChevronLeft className="h-4 w-4" />
            )}
          </button>
        </div>
      </aside>

      {/* Main content */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Admin top bar */}
        <header className="flex h-14 items-center justify-between border-b border-border/50 bg-white/80 backdrop-blur-sm px-6 shrink-0">
          <div className="flex items-center gap-3">
            <Badge
              className="bg-primary/8 text-primary border-primary/15 text-xs font-medium px-2 py-0.5"
            >
              Admin
            </Badge>
            <span className="text-border text-sm">/</span>
            <span className="text-sm text-muted-foreground">
              {location.pathname === "/admin"
                ? "Dashboard"
                : location.pathname
                    .split("/")
                    .filter(Boolean)
                    .slice(1)
                    .map((s) =>
                      s
                        .split("-")
                        .map((w) => w[0].toUpperCase() + w.slice(1))
                        .join(" ")
                    )
                    .join(" / ")}
            </span>
          </div>

          <div className="flex items-center gap-2">
            <DropdownMenu>
              <DropdownMenuTrigger asChild>
                <button className="flex items-center gap-2 rounded-lg px-2 py-1 hover:bg-muted/50 transition-colors">
                  <Avatar className="h-6 w-6">
                    {profile?.avatar_url && (
                      <AvatarImage src={profile.avatar_url} alt={displayName} />
